// Malayalam meanings, written with tools/builders/ml-meanings/apply-lib.py.
import type { MeaningPack } from '../../types';

export const mlLib13: MeaningPack = {
  lang: 'ml',
  texts: {
    "sundarakanda-58": {
      "verses": {
        "0.0": "അപ്പോൾ മഹേന്ദ്രപർവ്വതത്തിന്റെ ശിഖരത്തിൽ, ഹനുമാൻ നയിച്ച മഹാവാനരന്മാർ ഏറ്റവും വലിയ ആനന്ദം അനുഭവിച്ചു.",
        "0.1": "മഹാത്മാക്കളായ വാനരന്മാർ സന്തോഷത്തോടെ ഇരുന്നപ്പോൾ, ആനന്ദംകൊണ്ട് പുളകിതനായ ജാംബവാൻ, സന്തുഷ്ടനായ മഹാവാനരനോട് സംസാരിച്ചു:",
        "0.2": "വായുപുത്രനോട്, ദൗത്യത്തിന്റെ കഥ ചോദിച്ചുകൊണ്ട്: \"നീ ദേവിയെ എങ്ങനെ കണ്ടു? അവൾ അവിടെ എങ്ങനെ ജീവിക്കുന്നു?",
        "0.3": "ക്രൂരനായ പത്തുതലയൻ അവളോട് എങ്ങനെ പെരുമാറുന്നു? മഹാവാനരാ, ഇതെല്ലാം സത്യമായി ഞങ്ങളോട് പറയൂ.",
        "0.4": "നീ എങ്ങനെ ദേവിയെ അന്വേഷിച്ചു കണ്ടെത്തി, അവൾ മറുപടിയായി എന്തു പറഞ്ഞു? അത് കേട്ടശേഷം ഇനി എന്തുചെയ്യണമെന്ന് ഞങ്ങൾ വീണ്ടും തീരുമാനിക്കും.",
        "0.5": "ജ്ഞാനിയായവനേ, ഞങ്ങൾ അവിടെ ചെല്ലുമ്പോൾ എന്തു പറയണം, എന്ത് മറച്ചുവെക്കണം എന്ന് പറയൂ.\"",
        "0.6": "അങ്ങനെ കല്പിക്കപ്പെട്ട ഹനുമാൻ, ആനന്ദത്താൽ രോമാഞ്ചമണിഞ്ഞ്, സീതാദേവിക്ക് തല കുനിച്ച് വണങ്ങി മറുപടി പറഞ്ഞു:",
        "0.7": "\"അങ്ങയുടെ കൺമുന്നിൽവെച്ചുതന്നെ, സമുദ്രത്തിന്റെ തെക്കേ തീരത്ത് എത്തുക എന്ന ലക്ഷ്യത്തോടെ ഞാൻ മഹേന്ദ്രപർവ്വതശിഖരത്തിൽനിന്ന് ആകാശത്തേക്ക് ചാടി.",
        "0.8": "പോകുന്ന വഴിയിൽ തടസ്സമായി ഒരു ഭയങ്കരമായത് പ്രത്യക്ഷപ്പെട്ടു: മനോഹരമായ ഒരു ദിവ്യമായ സ്വർണ്ണശിഖരം ഞാൻ കണ്ടു.",
        "0.9": "അത് എന്റെ വഴി തടഞ്ഞുനിൽക്കുകയായിരുന്നു; ആ മഹാപർവ്വതത്തെ ഞാൻ തടസ്സമായി കരുതി. ആ ദിവ്യവും ശ്രേഷ്ഠവുമായ സ്വർണ്ണപർവ്വതത്തെ സമീപിച്ചപ്പോൾ,",
        "0.10": "\"ഇത് തകർക്കണം\" എന്ന് ഞാൻ മനസ്സിൽ ഉറപ്പിച്ചു. ആ മഹാപർവ്വതത്തെ ഞാൻ വാലുകൊണ്ട് അടിച്ചപ്പോൾ,",
        "0.11": "അതിന്റെ സൂര്യതേജസ്സുള്ള ശിഖരം ആയിരം കഷണങ്ങളായി ചിതറി. എന്റെ ഉദ്ദേശ്യം മനസ്സിലാക്കിയ ആ മഹാപർവ്വതം സംസാരിച്ചു.",
        "0.12": "എന്റെ ഹൃദയത്തെ സന്തോഷിപ്പിക്കുന്ന മധുരവാക്കുകളാൽ എന്നെ \"മകനേ\" എന്ന് വിളിച്ചുകൊണ്ട് അത് പറഞ്ഞു: \"വായുവിന്റെ സുഹൃത്തും നിന്റെ അമ്മാവനുമായ എന്നെ അറിയുക,",
        "0.13": "മഹാസമുദ്രത്തിൽ വസിക്കുന്ന, മൈനാകം എന്നറിയപ്പെടുന്ന ഞാൻ. പണ്ട്, മകനേ, മഹാപർവ്വതങ്ങൾക്ക് ചിറകുണ്ടായിരുന്നു;",
        "0.14": "അവ ഭൂമിയിൽ ഇഷ്ടംപോലെ സഞ്ചരിച്ച്, എല്ലാ ഭാഗത്തും അതിനെ ഉപദ്രവിച്ചു. പർവ്വതങ്ങളുടെ ഈ പെരുമാറ്റം കേട്ട്, പാകാസുരനെ നിഗ്രഹിച്ച മഹാനായ ഇന്ദ്രൻ,",
        "0.15": "ആ പ്രഭു വജ്രായുധംകൊണ്ട് അവയുടെ ചിറകുകൾ ആയിരക്കണക്കിന് മുറിച്ചുകളഞ്ഞു. എന്നാൽ എന്നെ അതിൽനിന്ന് രക്ഷിച്ചത് നിന്റെ മഹാത്മാവായ പിതാവ്,",
        "0.16": "വായുദേവൻ, എന്റെ കുഞ്ഞേ, എന്നെ വരുണന്റെ വാസസ്ഥലമായ സമുദ്രത്തിലേക്ക് എറിഞ്ഞവൻ. ശത്രുനിഗ്രഹിയേ, ഞാൻ രാഘവനെ സഹായിക്കണം.",
        "0.17": "രാമൻ ധർമ്മം പാലിക്കുന്നവരിൽ ഏറ്റവും ശ്രേഷ്ഠനാണ്; വീര്യത്തിൽ ഇന്ദ്രനുതുല്യനുമാണ്.' ഇത് മഹാനായ മൈനാകത്തിൽനിന്ന് കേട്ടപ്പോൾ,",
        "0.18": "ഞാൻ എന്റെ ദൗത്യത്തെക്കുറിച്ച് പർവ്വതത്തോട് പറഞ്ഞു; പോകാൻ മനസ്സ് ഉറച്ചു. അപ്പോൾ മഹാനായ മൈനാകം എനിക്ക് അനുമതി നൽകി.",
        "0.19": "ആ മഹാപർവ്വതം, മനുഷ്യരൂപവും പർവ്വതശരീരവും ഉൾപ്പെടെ, മഹാസമുദ്രത്തിൽ മറഞ്ഞുപോയി.",
        "0.20": "ഏറ്റവും വേഗത്തിൽ ഞാൻ ശേഷിച്ച വഴി തുടർന്നു; ദീർഘനേരം ആ പാതയിലൂടെ വേഗത്തിൽ സഞ്ചരിച്ചു.",
        "0.21": "പിന്നെ സർപ്പങ്ങളുടെ മാതാവായ സുരസയെ ഞാൻ കണ്ടു; സമുദ്രമധ്യത്തിൽവെച്ച് ആ ദേവി എന്നോട് പറഞ്ഞു:",
        "0.22": "\"വാനരശ്രേഷ്ഠാ, ദേവന്മാർ നിന്നെ എനിക്ക് ആഹാരമായി നിശ്ചയിച്ചിരിക്കുന്നു; അതിനാൽ ഞാൻ നിന്നെ ഭക്ഷിക്കും, ദേവന്മാർ അത് എനിക്കായി വിധിച്ചിരിക്കുന്നു.\"",
        "0.23": "സുരസ ഇങ്ങനെ പറഞ്ഞപ്പോൾ, കൈകൂപ്പി തല കുനിച്ച്, മുഖം വിളറിയവനായി ഞാൻ ഈ വാക്കുകൾ പറഞ്ഞു:",
        "0.24": "\"ദശരഥപുത്രനും ശത്രുക്കളെ ചുട്ടെരിക്കുന്നവനുമായ മഹാതേജസ്വിയായ രാമൻ, സഹോദരൻ ലക്ഷ്മണനോടും സീതയോടുമൊപ്പം ദണ്ഡകാരണ്യത്തിൽ പ്രവേശിച്ചു.",
        "0.25": "അദ്ദേഹത്തിന്റെ പത്നി സീതയെ ക്രൂരനായ രാവണൻ അപഹരിച്ചു. രാമന്റെ കല്പനപ്രകാരം ഞാൻ അദ്ദേഹത്തിന്റെ ദൂതനായി അവളുടെ അടുത്തേക്ക് പോകുന്നു.",
        "0.26": "നല്ല സ്ത്രീയേ, അവന്റെ രാജ്യത്ത് വസിക്കുന്ന അങ്ങ് രാമനെ സഹായിക്കണം. അല്ലെങ്കിൽ, തളരാത്ത കർമ്മങ്ങളുള്ള മൈഥിലിയെയും രാമനെയും കണ്ടശേഷം,",
        "0.27": "ഞാൻ വീണ്ടും നിന്റെ വായിൽത്തന്നെ വരും; ഇത് ഞാൻ സത്യമായി വാക്കു നൽകുന്നു.\" ഇഷ്ടരൂപം ധരിക്കാൻ കഴിവുള്ള സുരസയോട് ഞാൻ ഇത് പറഞ്ഞപ്പോൾ,",
        "0.28": "\"ആർക്കും എന്നെ കടന്നുപോകാനാവില്ല; ഇതാണ് എനിക്ക് ലഭിച്ച വരം\" എന്ന് അവൾ പറഞ്ഞു. സുരസ ഇങ്ങനെ പറഞ്ഞപ്പോൾ, ഞാൻ പത്തു യോജന നീളത്തിൽ എന്നെത്തന്നെ വലുതാക്കി.",
        "0.29": "ഒരു നിമിഷത്തിനകം, ഞാൻ അതിന്റെ പകുതി കൂടുതൽ വളർന്നു; അവൾ എന്റെ വലുപ്പത്തേക്കാൾ വലിയ വായ് തുറന്നു.",
        "0.30": "അവളുടെ പിളർന്ന വായ് കണ്ടപ്പോൾ ഞാൻ വീണ്ടും ചെറുതായി; ആ നിമിഷത്തിൽത്തന്നെ ഞാൻ ഒരു തള്ളവിരലിന്റെ വലുപ്പമായി.",
        "0.31": "വേഗത്തിൽ ഞാൻ അവളുടെ വായിൽ കടന്ന് ഉടനെ പുറത്തുവന്നു. അപ്പോൾ സുരസ സ്വന്തം രൂപത്തിൽ എന്നോട് പറഞ്ഞു:",
        "0.32": "\"വാനരശ്രേഷ്ഠാ, നല്ലവനേ, നിന്റെ ലക്ഷ്യം നിറവേറ്റാൻ സന്തോഷത്തോടെ പോകൂ; വൈദേഹിയെ മഹാത്മാവായ രാഘവനോട് ചേർക്കൂ.",
        "0.33": "ശക്തിശാലിയായ വാനരാ, സുഖമായിരിക്കുക; ഞാൻ നിന്നിൽ സന്തുഷ്ടയാണ്.\" അപ്പോൾ എല്ലാ ജീവികളും \"നന്നായി, നന്നായി!\" എന്ന് വിളിച്ച് എന്നെ പ്രശംസിച്ചു.",
        "0.34": "പിന്നെ ഞാൻ ഗരുഡനെപ്പോലെ വിശാലമായ ആകാശത്തിലേക്ക് പറന്നു; പക്ഷേ എന്റെ നിഴൽ പിടിക്കപ്പെട്ടു, ഒന്നും കാണാൻ കഴിയാതായി.",
        "0.35": "വേഗം തടസ്സപ്പെട്ടപ്പോൾ ഞാൻ പത്തു ദിക്കുകളിലേക്കും നോക്കി; എന്റെ ഗതി തടഞ്ഞത് എന്താണെന്ന് അവിടെ ഒന്നും കണ്ടില്ല.",
        "0.36": "അപ്പോൾ ചിന്ത വന്നു: \"ഇവിടെ ഒരു രൂപവും കാണാനില്ലാത്തപ്പോൾ, എന്റെ വഴിയിൽ ഉണ്ടായ ഈ തടസ്സം എന്താണ്?\"",
        "0.37": "ഞാൻ ആലോചിക്കുമ്പോൾ എന്റെ നോട്ടം താഴേക്ക് വീണു; അവിടെ വെള്ളത്തിൽ കിടക്കുന്ന ഒരു ഭയങ്കരിയായ രാക്ഷസിയെ ഞാൻ കണ്ടു.",
        "0.38": "ഭയമില്ലാതെ നിന്ന എന്നോട്, ആ ഭീകരി ഉച്ചത്തിൽ ചിരിച്ചുകൊണ്ട് ഈ വൃത്തികെട്ട വാക്കുകൾ പറഞ്ഞു:",
        "0.39": "\"ഭീമാകാരാ, എവിടേക്കാണ് പോകുന്നത്? എനിക്ക് വേണ്ട ആഹാരമാണ് നീ, ഞാൻ വിശക്കുന്നു. ദീർഘകാലമായി ആഹാരമില്ലാത്ത എന്റെ ശരീരത്തെ തൃപ്തിപ്പെടുത്തൂ.\"",
        "0.40": "\"ശരി\" എന്ന് പറഞ്ഞ് ഞാൻ അവളുടെ വാക്കുകൾ സ്വീകരിച്ചു; അവളുടെ വായുടെ വലുപ്പത്തേക്കാൾ വലുതായി എന്റെ ശരീരം വീർപ്പിച്ചു.",
        "0.41": "അവളുടെ വലിയതും ഭയങ്കരവുമായ വായ് എന്നെ വിഴുങ്ങാൻ വളർന്നുകൊണ്ടിരുന്നു; ഞാൻ എന്നെയോ, രൂപം മാറ്റാൻ ഞാൻ ചെയ്തതിനെയോ അവൾ മനസ്സിലാക്കിയില്ല.",
        "0.42": "പിന്നെ, കണ്ണിമവെട്ടുന്ന നേരംകൊണ്ട് എന്റെ വലിയ രൂപം ചുരുക്കി, ഞാൻ അവളുടെ ഹൃദയം പറിച്ചെടുത്ത് ആകാശത്തേക്ക് പറന്നു.",
        "0.43": "ഞാൻ ഹൃദയം പറിച്ചെടുത്ത ആ പർവ്വതസമാനമായ ഭയങ്കരജീവി, കൈകൾ വിരിച്ച്, ഉപ്പുവെള്ളമുള്ള കടലിൽ വീണു.",
        "0.44": "ആകാശത്ത് സഞ്ചരിക്കുന്ന മഹാത്മാക്കളുടെ മൃദുസ്വരങ്ങൾ ഞാൻ കേട്ടു: \"ഭയങ്കരിയായ രാക്ഷസി സിംഹിക ഹനുമാനാൽ വേഗത്തിൽ വധിക്കപ്പെട്ടിരിക്കുന്നു.\"",
        "0.45": "അവളെ വധിച്ചശേഷം എന്റെ അടിയന്തര ദൗത്യം ഓർത്ത് ഞാൻ മുന്നോട്ടുപോയി; ദൂരം താണ്ടിയശേഷം, പർവ്വതങ്ങളാൽ അലംകൃതമായ",
        "0.46": "സമുദ്രത്തിന്റെ തെക്കേ തീരം ഞാൻ കണ്ടു; അവിടെയാണ് ലങ്കാനഗരം സ്ഥിതിചെയ്യുന്നത്. സൂര്യൻ അസ്തമിച്ചപ്പോൾ, രാക്ഷസരുടെ വാസസ്ഥലമായ ആ നഗരത്തിൽ ഞാൻ പ്രവേശിച്ചു.",
        "0.47": "ഭയങ്കര ശക്തിയുള്ള രാക്ഷസന്മാർ എന്നെ തിരിച്ചറിഞ്ഞില്ല. ഞാൻ കടക്കുമ്പോൾ, യുഗാന്ത്യത്തിലെ മേഘംപോലെ തിളങ്ങുന്ന ഒരു സ്ത്രീ",
        "0.48": "എന്റെ മുന്നിൽ പൊങ്ങിവന്ന് ഉച്ചത്തിൽ ചിരിച്ചു. എന്നെ കൊല്ലാൻ ഉറച്ചവളായ അവളുടെ മുടി എരിയുന്ന തീപോലെയായിരുന്നു;",
        "0.49": "ആ ഭയങ്കരിയെ ഞാൻ ഇടത് മുഷ്ടികൊണ്ടുള്ള അടികൊണ്ട് കീഴടക്കി, രാത്രിയായപ്പോൾ അകത്ത് കടന്നു. അപ്പോൾ ഭയന്ന് അവൾ എന്നോട് പറഞ്ഞു:",
        "0.50": "\"വീരാ, നിന്റെ വീര്യത്താൽ കീഴടക്കപ്പെട്ട ലങ്കയാണ് ഞാൻ; അതിനാൽ നീ എല്ലാ രാക്ഷസന്മാരെയും ഒഴിവില്ലാതെ കീഴടക്കും.\"",
        "0.51": "രാത്രി മുഴുവൻ ഞാൻ അവിടെ ജനകന്റെ മകളെ തിരഞ്ഞു; രാവണന്റെ അന്തഃപുരത്തിലും ചെന്നു, എന്നാൽ മെലിഞ്ഞ അരക്കെട്ടുള്ള ആ സ്ത്രീയെ കണ്ടെത്തിയില്ല.",
        "0.52": "രാവണന്റെ കൊട്ടാരത്തിൽ സീതയെ കാണാതെ, ഞാൻ ദുഃഖസമുദ്രത്തിൽ വീണു; അതിന് തീരം കാണാനും കഴിഞ്ഞില്ല.",
        "0.53": "ദുഃഖിച്ചിരിക്കുമ്പോൾ, ഉയർന്ന സ്വർണ്ണമതിലിനാൽ ചുറ്റപ്പെട്ട ഒരു മനോഹരമായ കൊട്ടാരത്തോട്ടം ഞാൻ കണ്ടു.",
        "0.54": "ആ മതിൽ ചാടിക്കടന്നപ്പോൾ അത് മരങ്ങൾ നിറഞ്ഞതായി കണ്ടു; അശോകവനത്തിന്റെ നടുവിൽ ഒരു വലിയ ശിംശപാവൃക്ഷം നിന്നിരുന്നു.",
        "0.55": "ആ മരത്തിൽ കയറിയപ്പോൾ സ്വർണ്ണനിറമുള്ള വാഴത്തോട്ടം കണ്ടു; ശിംശപാവൃക്ഷത്തിനടുത്തുതന്നെ ഞാൻ ആ മനോഹരിയായ സ്ത്രീയെ കണ്ടു,",
        "0.56": "കറുത്തവളും യൗവനയുക്തയും താമരക്കണ്ണുകളുള്ളവളും; ഉപവാസത്താൽ മുഖം മെലിഞ്ഞ്, ആ ഒറ്റ വസ്ത്രം ധരിച്ച്, പൊടിയാൽ മുടി നരച്ചവളായി.",
        "0.57": "ദുഃഖവും വേദനയും കൊണ്ട് അവയവങ്ങൾ ക്ഷീണിച്ച സീത, ഭർത്താവിന്റെ ക്ഷേമത്തിൽ ഉറച്ചുനിന്ന്, ഭീകരരും ക്രൂരരുമായ രാക്ഷസിമാർ ചുറ്റിനിൽക്കെ.",
        "0.58": "മാംസവും രക്തവും ഭക്ഷിക്കുന്ന ആ രാക്ഷസിമാർക്കിടയിൽ, കടുവകൾക്കിടയിലെ പേടമാനെപ്പോലെ. ആവർത്തിച്ച് ഭീഷണിപ്പെടുത്തപ്പെടുന്ന അവളെ ഞാൻ രാക്ഷസിമാർക്കിടയിൽ കണ്ടു,",
        "0.59": "ഒറ്റ ജടയണിഞ്ഞ്, ദയനീയയായി, ഭർത്താവിനെക്കുറിച്ചുള്ള ചിന്തയിൽ പൂർണ്ണമായി മുഴുകി, നിലത്ത് ഉറങ്ങി, മഞ്ഞുകാലം വരുമ്പോൾ വാടിയ താമരച്ചെടിപോലെ വിളറിയവളായി.",
        "0.60": "അവൾ രാവണനിൽനിന്ന് മുഖം തിരിച്ച്, മരിക്കാൻ ഉറച്ചിരുന്നു. ഒടുവിൽ, മാൻമിഴിയായവളെ ഞാൻ ബുദ്ധിമുട്ടി വേഗത്തിൽ കണ്ടെത്തി.",
        "0.61": "രാമന്റെ ഐശ്വര്യവതിയായ പത്നിയെ അങ്ങനെയുള്ള അവസ്ഥയിൽ കണ്ടപ്പോൾ, ഞാൻ ശിംശപാവൃക്ഷത്തിൽത്തന്നെ നിന്ന് നിരീക്ഷിച്ചു.",
        "0.62": "അപ്പോൾ രാവണന്റെ കൊട്ടാരത്തിൽ, അരഞ്ഞാണങ്ങളുടെയും കാൽച്ചിലമ്പുകളുടെയും കിലുക്കത്തോടൊപ്പം ഒരു വലിയ, ഗംഭീരമായ കോലാഹലം ഞാൻ കേട്ടു.",
        "0.63": "വലിയ ഭയം തോന്നി, ഞാൻ എന്റെ രൂപം ചുരുക്കി, കുറ്റിക്കാട്ടിലെ പക്ഷിയെപ്പോലെ ശിംശപാവൃക്ഷത്തിൽ ഒളിച്ചിരുന്നു.",
        "0.64": "പിന്നെ രാവണന്റെ ഭാര്യമാരും ശക്തനായ രാവണനും തന്നെ സീത ഇരിക്കുന്ന സ്ഥലത്തേക്ക് വന്നു.",
        "0.65": "രാക്ഷസരാജാവിനെ കണ്ടപ്പോൾ, സുന്ദരിയായ സീത തന്റെ തുടകൾ ഉള്ളിലേക്ക് ചേർത്ത്, നിറഞ്ഞ മാറുകൾ കൈകൾകൊണ്ട് മറച്ചു.",
        "0.66": "അവൾ ഭയന്നും അതിയായി വേദനിച്ചും ഇങ്ങോട്ടും അങ്ങോട്ടും നോക്കി; സംരക്ഷകനെ കാണാതെ, വിറച്ചുകൊണ്ട്, ആ പാവം സ്ത്രീ.",
        "0.67": "പത്തുകഴുത്തുള്ളവൻ, ആഴത്തിൽ ദുഃഖിച്ചിരിക്കുന്ന സീതയുടെ മുന്നിൽ തല കുനിച്ച് വീണ് അവളോട് പറഞ്ഞു: \"എന്നെ ഉയർന്ന ബഹുമാനത്തോടെ കാണൂ.\"",
        "0.68": "\"അഹങ്കാരിയേ, നീ അഹങ്കാരത്താൽ എന്നെ സ്വീകരിക്കില്ലെങ്കിൽ, രണ്ടു മാസം കഴിഞ്ഞ് സീതേ, ഞാൻ നിന്റെ രക്തം കുടിക്കും.\"",
        "0.69": "ക്രൂരനായ രാവണന്റെ ഈ വാക്കുകൾ കേട്ട്, സീത വലിയ കോപത്തോടെ ഈ ശ്രേഷ്ഠമായ മറുപടി നൽകി:",
        "0.70": "\"രാക്ഷസരിൽ ഏറ്റവും നീചനായവനേ! ഞാൻ അപാരതേജസ്വിയായ, ഇക്ഷ്വാകുവംശത്തിലെ പ്രഭുവായ രാമന്റെ പത്നിയാണ്; ദശരഥന്റെ മരുമകളാണ്.",
        "0.71": "പറയാൻ പാടില്ലാത്തത് പറയുന്നവനേ, നിന്റെ നാവ് എങ്ങനെ അടർന്നുവീണില്ല? നീചനേ, എന്റെ ഭർത്താവ് അവിടെ ഇല്ലാത്തപ്പോൾ, എന്ത് വീര്യമാണ് നിനക്കുള്ളത്,",
        "0.72": "ആ മഹാനറിയാതെ എന്നെ അപഹരിച്ച് കൊണ്ടുപോയി, പാപിയേ? നീ രാമനോട് തുല്യനല്ല; അദ്ദേഹത്തിന്റെ ഭൃത്യനാകാൻ പോലും നീ യോഗ്യനല്ല.",
        "0.73": "രാഘവൻ അജയ്യനും സത്യവാനും വീരനും യുദ്ധപ്രിയനുമാണ്.\" ജാനകി ഇത്തരം കഠിനവാക്കുകളാൽ സംസാരിച്ചപ്പോൾ, പത്തുമുഖനായവൻ",
        "0.74": "ശ്മശാനചിതപോലെ പെട്ടെന്ന് കോപത്താൽ ജ്വലിച്ചു; ക്രൂരമായ കണ്ണുകൾ ഉരുട്ടി, വലതു മുഷ്ടി ഉയർത്തി,",
        "0.75": "മൈഥിലിയെ കൊല്ലാൻ ഒരുങ്ങി; സ്ത്രീകൾ ഭയന്ന് നിലവിളിച്ചു. സ്ത്രീകൾക്കിടയിൽനിന്ന് ആ ദുഷ്ടന്റെ ഭാര്യ മുന്നോട്ട് ചാടി,",
        "0.76": "ശ്രേഷ്ഠയായ മണ്ഡോദരി; അവനെ തടഞ്ഞു. ആഗ്രഹത്താൽ പീഡിതനായ അവനോട് അവൾ മധുരമായി സംസാരിച്ചു:",
        "0.77": "\"ഇന്ദ്രനുതുല്യ വീര്യമുള്ളവനേ, നിനക്ക് സീതയോട് എന്താണ് വേണ്ടത്? ഇന്ന് എന്നോടൊപ്പം ആനന്ദിക്കൂ; ജാനകി എന്നെക്കാൾ മികച്ചവളല്ല.",
        "0.78": "ദേവന്മാരുടെയും ഗന്ധർവ്വന്മാരുടെയും യക്ഷന്മാരുടെയും പുത്രിമാരോടൊപ്പം, പ്രഭോ, ആനന്ദിക്കൂ; സീതയെക്കൊണ്ട് നിനക്കെന്ത് കാര്യം?\"",
        "0.79": "അപ്പോൾ ആ സ്ത്രീകൾ ഒന്നിച്ചുകൂടി, ശക്തനായ രാത്രിഞ്ചരനെ വേഗം ഉയർത്തി, സ്വന്തം കൊട്ടാരത്തിലേക്ക് കൊണ്ടുപോയി.",
        "0.80": "പത്തുകഴുത്തുള്ളവൻ പോയശേഷം, വികൃതമുഖമുള്ള രാക്ഷസികൾ ക്രൂരവും ഭയങ്കരവുമായ വാക്കുകളാൽ സീതയെ ഭീഷണിപ്പെടുത്തി.",
        "0.81": "ജാനകി അവരുടെ വാക്കുകളെ പുല്ലുപോലെ കണക്കാക്കി; സീതയ്ക്കെതിരെയുള്ള അവരുടെ ഗർജ്ജനം ഒന്നുമല്ലാതായി.",
        "0.82": "വെറുതെ ഗർജ്ജിച്ച മാംസഭുക്കുകളായ രാക്ഷസിമാർ പരിഭ്രമിച്ചു; സീതയുടെ ഉറച്ച തീരുമാനം അവർ രാവണനെ അറിയിച്ചു.",
        "0.83": "പിന്നെ എല്ലാവരും ഒന്നിച്ച്, പ്രതീക്ഷ തകർന്ന്, ശ്രമം ഉപേക്ഷിച്ച്, അവളെ ഉപദ്രവിച്ചശേഷം ഉറങ്ങി.",
        "0.84": "അവർ ഉറങ്ങുമ്പോൾ, ഭർത്താവിന്റെ ക്ഷേമത്തിൽ മുഴുകിയ സീത ദയനീയമായി വിലപിച്ചു, ആഴത്തിലുള്ള ദുഃഖത്തിൽ വേദനിച്ചു.",
        "0.85": "അവർക്കിടയിൽനിന്ന് ത്രിജട എഴുന്നേറ്റ് പറഞ്ഞു: \"നിങ്ങൾ തമ്മിൽ വേഗം തിന്നൂ; പക്ഷേ കറുത്ത കണ്ണുകളുള്ള സീതയെ തിന്നരുത്,",
        "0.86": "ജനകന്റെ പുണ്യവതിയായ മകളും ദശരഥന്റെ മരുമകളുമാണവൾ. ഇന്ന് ഞാൻ ഒരു ഭയങ്കര സ്വപ്നം കണ്ടു; അത് മുടി എഴുന്നേൽപ്പിക്കുന്നതാണ്,",
        "0.87": "രാക്ഷസരുടെ നാശത്തെയും ഭർത്താവിന്റെ വിജയത്തെയും മുൻകൂട്ടി അറിയിക്കുന്നത്. അവൾക്ക് നമ്മളെ, രാക്ഷസിമാരുടെ സംഘത്തെ, രാഘവനിൽനിന്ന് സംരക്ഷിക്കാൻ കഴിയും.",
        "0.88": "വൈദേഹിയോട് കരുണയ്ക്കായി അപേക്ഷിക്കാം; ഇതാണ് ഏറ്റവും നല്ലതെന്ന് ഞാൻ കരുതുന്നു. ദുഃഖിതയായ ഒരാളെക്കുറിച്ച് ഇങ്ങനെയുള്ള സ്വപ്നം കാണുമ്പോൾ,",
        "0.89": "അവൾ അവളുടെ പല ദുഃഖങ്ങളിൽനിന്നും മോചിതയായി പരമസുഖം നേടുന്നു. ജനകപുത്രി മൈഥിലി വിനയത്തോടെയുള്ള വണക്കംകൊണ്ട് എളുപ്പത്തിൽ മനസ്സലിയുന്നവളാണ്;",
        "0.90": "മഹാഭയത്തിൽനിന്ന് അവൾക്ക് നിങ്ങളെ, രാക്ഷസിമാരേ, സംരക്ഷിക്കാൻ കഴിയും.\" അപ്പോൾ ആ വിനീതയായ യുവതി, ഭർത്താവിന്റെ വരാനിരിക്കുന്ന വിജയത്തിൽ സന്തോഷിച്ച്,",
        "0.91": "\"അത് സത്യമെങ്കിൽ ഞാൻ നിങ്ങളുടെ അഭയമാകും\" എന്ന് പറഞ്ഞു. ഇത്ര ഭയങ്കരമായ അവസ്ഥയിൽ സീതയെ കണ്ടപ്പോൾ,",
        "0.92": "ഞാൻ കുറച്ചുനേരം ആലോചിച്ചു, പക്ഷേ മനസ്സിന് സമാധാനം കിട്ടിയില്ല. ജാനകിയോട് സംസാരിക്കാനുള്ള ഒരു മാർഗ്ഗം ഞാൻ ചിന്തിച്ചു:",
        "0.93": "ഇക്ഷ്വാകുവംശത്തിന്റെ പ്രശംസയോടെ ഞാൻ തുടങ്ങി. രാജർഷിമാരുടെ നാമങ്ങളാൽ അലംകൃതമായ എന്റെ വാക്കുകൾ കേട്ട്,",
        "0.94": "കണ്ണുനീരിൽ മറഞ്ഞ കണ്ണുകളോടെ ദേവി എനിക്ക് മറുപടി പറഞ്ഞു: \"വാനരശ്രേഷ്ഠാ, നീ ആരാണ്? നിന്നെ ആരയച്ചു, നീ ഇവിടെ എങ്ങനെ വന്നു?",
        "0.95": "രാമനുമായുള്ള നിന്റെ സൗഹൃദം എന്താണ്? ദയവായി അത് പറയൂ.\" അവളുടെ വാക്കുകൾ കേട്ട്, ഞാൻ മറുപടിയായി പറഞ്ഞു:",
        "0.96": "\"ദേവീ, നിന്റെ ഭർത്താവ് രാമന് ഭയങ്കര വീര്യമുള്ള ഒരു സഖ്യകക്ഷിയുണ്ട്; ശക്തനും വീരനുമായ സുഗ്രീവൻ, വാനരരാജാവ്.",
        "0.97": "ഞാൻ അദ്ദേഹത്തിന്റെ ഭൃത്യൻ, ഹനുമാൻ എന്ന് അറിയുക; തളരാത്ത കർമ്മങ്ങളുള്ള നിന്റെ ഭർത്താവ് രാമൻ നിന്റെ അടുത്തേക്ക് അയച്ചതാണ് ഞാൻ.",
        "0.98": "ഐശ്വര്യവതിയായ ദേവീ, പുരുഷശ്രേഷ്ഠനായ ദശരഥപുത്രൻതന്നെ അങ്ങേക്ക് അടയാളമായി നൽകിയ ഈ മോതിരം.",
        "0.99": "\"ദേവീ, അങ്ങ് എന്നോട് പറയണം എന്നാണ് എന്റെ ആഗ്രഹം: ഞാൻ എന്ത് ചെയ്യണം? അങ്ങയെ രാമന്റെയും ലക്ഷ്മണന്റെയും അടുത്തേക്ക് കൊണ്ടുപോകണമോ? അങ്ങയുടെ മറുപടി എന്താണ്?\"",
        "0.100": "ഇത് കേട്ട് മനസ്സിലാക്കിയ ജനകപുത്രി സീത പറഞ്ഞു: \"രാഘവൻ രാവണനെ പിഴുതെറിഞ്ഞ് എന്നെ തിരികെ കൊണ്ടുപോകട്ടെ.\"",
        "0.101": "ശ്രേഷ്ഠയും കളങ്കമില്ലാത്തവളുമായ ദേവിക്ക് ഞാൻ തല കുനിച്ച് വണങ്ങി; രാഘവന്റെ ഹൃദയത്തെ സന്തോഷിപ്പിക്കുന്ന ഒരു അടയാളം ഞാൻ അവളോട് ചോദിച്ചു.",
        "0.102": "അപ്പോൾ സീത എന്നോട് പറഞ്ഞു: \"ബലിഷ്ഠബാഹുവായ രാമൻ നിന്നെ ഉയർന്ന ബഹുമാനത്തോടെ കാണുന്ന ഈ ശ്രേഷ്ഠമായ രത്നം നീ എടുക്കൂ.\"",
        "0.103": "ഇങ്ങനെ പറഞ്ഞ്, വലിയ ദുഃഖത്തിലായ ആ സുന്ദരി, ഏറ്റവും ശ്രേഷ്ഠമായ ആ രത്നം എനിക്ക് നൽകി; വാമൊഴിയായുള്ള ഒരു സന്ദേശവും നൽകി.",
        "0.104": "പിന്നെ ഞാൻ ഏകാഗ്രമനസ്സോടെ രാജകുമാരിക്ക് വണങ്ങി, ഭക്തിയോടെ അവളെ വലംവെച്ചു; ഇവിടേക്ക് മടങ്ങിവരാൻ മനസ്സ് ഉറപ്പിച്ചവനായി.",
        "0.105": "ആലോചിച്ചശേഷം അവൾ മറുപടിയായി വീണ്ടും സംസാരിച്ചു: \"ഹനുമാനേ, എന്നെക്കുറിച്ചുള്ള എല്ലാ കാര്യങ്ങളും നീ രാഘവനോട് പറയണം,",
        "0.106": "അത് കേട്ട് ഇരുവീരന്മാരായ രാമനും ലക്ഷ്മണനും സുഗ്രീവനോടൊപ്പം വൈകാതെ ഇവിടെ എത്തട്ടെ; ഇത് ചെയ്യണം.",
        "0.107": "അല്ലാത്തപക്ഷം എനിക്ക് രണ്ടു മാസം മാത്രമേ ആയുസ്സുള്ളൂ; കാകുത്സ്ഥൻ എന്നെ കാണില്ല; സംരക്ഷകനില്ലാത്തവളെപ്പോലെ ഞാൻ മരിക്കും.\"",
        "0.108": "ആ ദയനീയമായ വാക്കുകൾ കേട്ടപ്പോൾ എന്നിൽ കോപം ഉണർന്നു; ഇനി ചെയ്യാനുള്ള കാര്യത്തിൽ എന്തൊക്കെ ശേഷിക്കുന്നു എന്ന് ഞാൻ കണ്ടു.",
        "0.109": "പിന്നെ എന്റെ ശരീരം പർവ്വതംപോലെ വലുതായി; യുദ്ധത്തിന് ആവേശത്തോടെ ഞാൻ അവന്റെ തോട്ടം നശിപ്പിച്ചു തുടങ്ങി.",
        "0.110": "ഉണർന്ന വികൃതമുഖികളായ രാക്ഷസിമാർ, മൃഗങ്ങളും പക്ഷികളും ഭയന്ന് പരിഭ്രമിച്ചിരിക്കുന്ന ആ തകർന്ന തോട്ടം കണ്ടു.",
        "0.111": "തോട്ടത്തിൽ എന്നെ കണ്ട് അവർ പല ഭാഗത്തുനിന്നും ഒരുമിച്ചുകൂടി, വേഗം ചെന്ന് രാവണനോട് പറഞ്ഞു:",
        "0.112": "\"രാജാവേ, അങ്ങയുടെ ശക്തിയെക്കുറിച്ച് ഒന്നും അറിയാത്ത ഒരു ദുഷ്ടവാനരൻ അങ്ങയുടെ ഈ അജയ്യമായ തോട്ടം തകർത്തിരിക്കുന്നു, ശക്തനായവനേ.",
        "0.113": "രാജാവേ, ആ അപരാധിയുടെ വിഡ്ഢിത്തം ഇതാണ്; അവൻ വീണ്ടും രക്ഷപ്പെടാതിരിക്കാൻ അവനെ വേഗം വധിക്കാൻ കല്പിക്കൂ.\"",
        "0.114": "ഇത് കേട്ട രാക്ഷസരാജാവ്, രാവണന്റെ ഇഷ്ടം നിറവേറ്റുന്ന, ജയിക്കാൻ അതിപ്രയാസമുള്ള കിങ്കരന്മാർ എന്ന രാക്ഷസന്മാരെ അയച്ചു.",
        "0.115": "കുന്തങ്ങളും ഗദകളും ധരിച്ച അവരിൽ എൺപതിനായിരം പേരെ, ആ തോട്ടത്തിന്റെ ഭാഗത്ത് ഞാൻ ഇരുമ്പുദണ്ഡുകൊണ്ട് വധിച്ചു.",
        "0.116": "ആ കൂട്ടക്കൊലയിൽനിന്ന് രക്ഷപ്പെട്ടവർ വേഗത്തിൽ ഓടിപ്പോയി, തങ്ങളുടെ സൈന്യം എന്നെ നശിപ്പിച്ചു എന്ന് രാവണനോട് അറിയിച്ചു.",
        "0.117": "പിന്നെ ആ മനോഹരമായ ദേവാലയസമാന കൊട്ടാരം ആക്രമിക്കാൻ എനിക്ക് തോന്നി; അവിടെ നിലകൊണ്ടിരുന്ന നൂറ് രാക്ഷസരെ ഒരു തൂണുകൊണ്ട് ഞാൻ കൊന്നു,",
        "0.118": "കോപത്തോടെ ലങ്കയുടെ ആ അലങ്കാരം ഞാൻ തകർത്തു. അപ്പോൾ രാവണൻ, പ്രഹസ്തന്റെ മകൻ ജംബുമാലിയോട് പുറപ്പെടാൻ കല്പിച്ചു",
        "0.119": "ഭയങ്കരവും ഭീകരവുമായ രൂപമുള്ള പല രാക്ഷസന്മാരോടൊപ്പം. യുദ്ധത്തിൽ വിദഗ്ധനായ ആ ശക്തനായ രാക്ഷസൻ,",
        "0.120": "അനുയായികളോടൊപ്പം ഏറ്റവും ഭയങ്കരമായ ഇരുമ്പുദണ്ഡുകൊണ്ട് ഞാൻ വധിച്ചു. അത് കേട്ട് രാക്ഷസരാജാവായ രാവണൻ തന്റെ മന്ത്രിമാരുടെ ശക്തരായ പുത്രന്മാരെ അയച്ചു;",
        "0.121": "ശക്തരായ കാലാൾപ്പടയാൽ പിന്തുണയ്ക്കപ്പെട്ട അവരെയും, എല്ലാവരെയും, ഒറ്റ ഇരുമ്പുദണ്ഡുകൊണ്ട് ഞാൻ യമലോകത്തേക്ക് അയച്ചു.",
        "0.122": "മന്ത്രിപുത്രന്മാർ യുദ്ധത്തിൽ വേഗത്തിൽ വധിക്കപ്പെട്ടു എന്ന് കേട്ട രാവണൻ, തന്റെ സൈന്യത്തിലെ അഞ്ചു വീരസേനാപതികളെ അയച്ചു.",
        "0.123": "അവരെയെല്ലാം അവരുടെ സൈന്യത്തോടൊപ്പം ഞാൻ വധിച്ചു. പിന്നെയും പത്തുകഴുത്തുള്ളവൻ തന്റെ ശക്തനായ പുത്രൻ അക്ഷനെ",
        "0.124": "അനേകം രാക്ഷസരോടൊപ്പം യുദ്ധത്തിലേക്ക് അയച്ചു. മണ്ഡോദരിയുടെ ആ പുത്രൻ, യുദ്ധനിപുണനായ രാജകുമാരൻ,",
        "0.125": "പെട്ടെന്ന് ആകാശത്തേക്ക് ഉയർന്നു; ഞാൻ അവനെ കാലിൽ പിടിച്ച്, നൂറുതവണ ചുഴറ്റി, ഞെരിച്ചുകളഞ്ഞു.",
        "0.126": "അക്ഷൻ പുറപ്പെട്ട് ഞെരിക്കപ്പെട്ടു എന്ന് കേട്ട പത്തുമുഖനായ രാവണൻ ഏറെ കോപത്തോടെ തന്റെ രണ്ടാമത്തെ പുത്രനായ ഇന്ദ്രജിത്തിനോട് കല്പിച്ചു,",
        "0.127": "യുദ്ധത്തിൽ ശക്തനും ഉഗ്രനുമായവനെ. ആ മുഴുവൻ സൈന്യത്തെയും, രാക്ഷസരിലെ ആ കാളയെയും കൂടി,",
        "0.128": "യുദ്ധത്തിൽ ഞാൻ നിർവീര്യരാക്കി; ഏറ്റവും വലിയ ആനന്ദം ഞാൻ അനുഭവിച്ചു. ആ ശക്തനും മഹാബാഹുവുമായവൻ വലിയ വിശ്വാസത്തോടെ",
        "0.129": "രാവണനാൽ, അഹങ്കാരംകൊണ്ട് ഉഗ്രരായ വീരന്മാരോടൊപ്പം അയക്കപ്പെട്ടിരുന്നു. ഞാൻ തടുക്കാനാവാത്തവനാണെന്നും സ്വന്തം സൈന്യം തകർക്കപ്പെട്ടു എന്നും മനസ്സിലാക്കി,",
        "0.130": "വേഗമുള്ളവനായിരുന്നിട്ടും അവൻ എന്നെ ബ്രഹ്മാസ്ത്രംകൊണ്ട് ബന്ധിച്ചു; പിന്നെ അവിടെയുണ്ടായിരുന്ന രാക്ഷസന്മാർ എന്നെ കയറുകൊണ്ടും കെട്ടി.",
        "0.131": "അവർ എന്നെ പിടികൂടി രാവണന്റെ മുന്നിൽ കൊണ്ടുവന്നു. എന്നെ കണ്ടപ്പോൾ ദുഷ്ടനായ രാവണൻ എന്നോട് സംസാരിച്ചു,",
        "0.132": "ഞാൻ ലങ്കയിൽ എന്തിന് വന്നു, രാക്ഷസരെ എന്തിന് കൊന്നു എന്ന് ചോദിച്ചു. അവിടെ നടന്ന യുദ്ധം ഉൾപ്പെടെ എല്ലാം സീതയ്ക്കുവേണ്ടിയായിരുന്നു എന്ന് ഞാൻ അവനോട് പറഞ്ഞു:",
        "0.133": "\"പ്രഭോ, അവളെ കാണാനുള്ള ആഗ്രഹത്താലാണ് ഞാൻ അങ്ങയുടെ കൊട്ടാരത്തിൽ വന്നത്. ഞാൻ ഹനുമാൻ, വായുദേവന്റെ യഥാർത്ഥ പുത്രനായ വാനരൻ.",
        "0.134": "രാമന്റെ ദൂതനായും സുഗ്രീവന്റെ വാനരമന്ത്രിയായും എന്നെ അറിയുക. രാമന്റെ ദൗത്യവുമായി ഞാൻ ഇവിടെ അങ്ങയുടെ അടുത്ത് വന്നിരിക്കുന്നു.",
        "0.135": "ഞാൻ കൊണ്ടുവന്ന സന്ദേശവും കേൾക്കുക. രാക്ഷസരാജാവേ, വാനരരാജാവ് അങ്ങേക്ക് ആലോചിച്ച ഒരു വാക്ക് അയക്കുന്നു.",
        "0.136": "ശ്രേഷ്ഠനായ സുഗ്രീവൻ അങ്ങയുടെ ക്ഷേമം അന്വേഷിക്കുകയും, ധർമ്മത്തിനും അർത്ഥത്തിനും കാമത്തിനും യോജിച്ച, ഹിതകരവും നന്മയുള്ളതുമായ ഈ ഉപദേശം നൽകുകയും ചെയ്തിരിക്കുന്നു:",
        "0.137": "\"വൃക്ഷസമൃദ്ധമായ ഋശ്യമൂകപർവ്വതത്തിൽ ഞാൻ വസിക്കുമ്പോൾ, യുദ്ധവീരനായ രാഘവൻ എന്റെ സുഹൃത്തായി.",
        "0.138": "\"എന്റെ ഭാര്യയെ ഒരു രാക്ഷസൻ അപഹരിച്ചിരിക്കുന്നു; ഇതിൽ സഹായിക്കാൻ നീ എന്നോട് സഖ്യം ചെയ്യണം\" എന്ന് അവൻ രാജാവേ, എന്നോട് പറഞ്ഞു.",
        "0.139": "വാലിയാൽ രാജ്യം അപഹരിക്കപ്പെട്ട ഞാൻ സുഗ്രീവനുമായി, ലക്ഷ്മണനോടൊപ്പമുള്ള ഭഗവാൻ രാഘവൻ അഗ്നിസാക്ഷിയായി സഖ്യമുണ്ടാക്കി.",
        "0.140": "ഒറ്റ അമ്പുകൊണ്ട് വാലിയെ യുദ്ധത്തിൽ വധിച്ച്, ചാടിക്കളിക്കുന്നവരുടെ നാഥനായ വാനരരാജാവായി എന്നെ മഹാനാക്കി.",
        "0.141": "ഇവിടെ ഞങ്ങൾ ഹൃദയപൂർവ്വം അദ്ദേഹത്തെ സഹായിക്കണം. അതിനാൽ ധർമ്മപ്രകാരം ഈ ദൂതനെ ഞാൻ അങ്ങയുടെ അടുത്തേക്ക് അയച്ചിരിക്കുന്നു.",
        "0.142": "വീരന്മാരായ വാനരന്മാർ അങ്ങയുടെ സൈന്യത്തെ നശിപ്പിക്കുന്നതിന് മുമ്പ്, സീതയെ വേഗം കൊണ്ടുവന്ന് രാഘവന് തിരിച്ചുനൽകൂ.",
        "0.143": "ക്ഷണിച്ചാൽ ദേവന്മാരുടെ സന്നിധിയിൽപ്പോലും ചെല്ലുന്ന വാനരന്മാരുടെ ശക്തി പണ്ടുമുതൽക്കേ ആർക്കാണ് അറിയാത്തത്?\"",
        "0.144": "\"വാനരരാജാവ് അങ്ങയോട് ഇങ്ങനെ പറയുന്നു\" എന്ന് ഞാൻ അവനോട് പറഞ്ഞു. അപ്പോൾ അവൻ കോപത്തോടെ എന്നെ നോക്കി, കണ്ണുകൊണ്ട് ദഹിപ്പിക്കാൻ എന്നപോലെ.",
        "0.145": "ക്രൂരകർമ്മങ്ങളുള്ള ആ രാക്ഷസൻ, ദുഷ്ടനായ രാവണൻ, എന്റെ ശക്തി അറിയാതെ, എന്നെ വധിക്കാൻ കല്പിച്ചു.",
        "0.146": "അപ്പോൾ അവന്റെ സഹോദരൻ, ജ്ഞാനിയായ വിഭീഷണൻ, എനിക്കുവേണ്ടി രാക്ഷസരാജാവിനോട് അപേക്ഷിച്ചു:",
        "0.147": "\"അങ്ങനെയല്ല, രാക്ഷസശ്രേഷ്ഠാ; ഈ തീരുമാനം ഉപേക്ഷിക്കൂ. അങ്ങ് സ്വീകരിക്കുന്ന മാർഗ്ഗം രാജനീതിശാസ്ത്രത്തിന് വിരുദ്ധമാണ്.",
        "0.148": "ദൂതനെ വധിക്കുന്നത് രാജനീതിയുടെ ഗ്രന്ഥങ്ങളിൽ ഒരിടത്തും കാണുന്നില്ല, രാക്ഷസാ; ദൂതൻ പറയാൻ ഏല്പിക്കപ്പെട്ടത് മാത്രമേ പറയൂ.",
        "0.149": "അതുല്യവീര്യനായവനേ, ദൂതൻ വലിയ തെറ്റ് ചെയ്താലും അംഗഭംഗമാണ് വിധിക്കപ്പെട്ടത്; ശാസ്ത്രപ്രകാരം വധമില്ല.\"",
        "0.150": "വിഭീഷണൻ ഇങ്ങനെ പറഞ്ഞപ്പോൾ, രാവണൻ ആ രാക്ഷസരോട് കല്പിച്ചു: \"ഇവന്റെ ഈ വാൽതന്നെ ഇന്ന് കത്തിക്കൂ.\"",
        "0.151": "അവന്റെ കല്പന കേട്ട് അവർ എന്റെ വാൽ മുഴുവൻ ചണനാരുകൊണ്ടും പഞ്ഞിത്തുണികൊണ്ടും പൊതിഞ്ഞു.",
        "0.152": "പിന്നെ പൂർണ്ണസജ്ജരായ ആ ക്രൂരരാക്ഷസർ എന്റെ വാലിന് തീകൊളുത്തി; വടികൊണ്ടും മുഷ്ടികൊണ്ടും എന്നെ അടിച്ചുകൊണ്ട്.",
        "0.153": "പല കയറുകളാൽ ബന്ധിക്കപ്പെട്ടും രാക്ഷസരാൽ മുറുകെ പിടിക്കപ്പെട്ടും ഇരുന്നെങ്കിലും എനിക്ക് ഒട്ടും വേദന തോന്നിയില്ല; പകൽസമയത്ത് നഗരം കാണണമെന്ന് ഞാൻ ആഗ്രഹിച്ചിരുന്നു.",
        "0.154": "പിന്നെ ആ വീരരാക്ഷസർ നഗരകവാടത്തിൽ വന്ന്, ബന്ധിതനും തീയിൽ പൊതിഞ്ഞവനുമായ എന്നെ രാജവീഥിയിലൂടെ വിളിച്ചുപറഞ്ഞ് നടത്തി.",
        "0.155": "പിന്നെ ഞാൻ എന്റെ ഭീമാകാരമായ രൂപം വീണ്ടും ചുരുക്കി, ആ ബന്ധനങ്ങളിൽനിന്ന് ഊരി, സ്വാഭാവികരൂപത്തിൽ വീണ്ടും നിന്നു.",
        "0.156": "ഇരുമ്പുദണ്ഡെടുത്ത് ആ രാക്ഷസരെ ഞാൻ വധിച്ചു; പിന്നെ നഗരകവാടത്തിലേക്ക് വേഗത്തിൽ ചാടിക്കയറി.",
        "0.157": "ജ്വലിക്കുന്ന വാലുമായി, ഭയമില്ലാതെ, യുഗാന്ത്യത്തിലെ അഗ്നി സർവ്വജീവികളെയും ദഹിപ്പിക്കുന്നതുപോലെ, ഗോപുരങ്ങളും കവാടങ്ങളുമുള്ള ആ നഗരത്തെ ഞാൻ ചുട്ടെരിച്ചു.",
        "0.158": "\"ലങ്കയുടെ ഒരു ഭാഗവും കത്താതെ കാണാനില്ലാത്തതിനാൽ ജാനകി നശിച്ചുപോയെന്ന് വ്യക്തം; നഗരം മുഴുവൻ ചാമ്പലായിരിക്കുന്നു.",
        "0.159": "ലങ്ക ദഹിപ്പിക്കുമ്പോൾ സീതയെയും ദഹിപ്പിച്ചിരിക്കുന്നു, സംശയമില്ല; രാമന്റെ ഈ മഹാദൗത്യം ഞാൻ നിഷ്ഫലമാക്കി.\"",
        "0.160": "ഇങ്ങനെ ദുഃഖത്താൽ വിഷമിച്ച് ഞാൻ ആധിയിൽ വീണു. അപ്പോൾ ചാരണന്മാരുടെ ശുഭവാക്കുകൾ ഞാൻ കേട്ടു,",
        "0.161": "അവർ അദ്ഭുതകരമായ വാർത്ത പറയുകയായിരുന്നു: \"ജാനകി ദഹിച്ചിട്ടില്ല.\" ആ അദ്ഭുത വചനം കേട്ടപ്പോൾ എന്റെ മനസ്സിൽ ചിന്ത വന്നു:",
        "0.162": "\"ജാനകി സത്യമായും ദഹിക്കാതെയിരിക്കുന്നു\" എന്ന്; ശകുനങ്ങളും അത് കാണിച്ചു: എന്റെ വാൽ ജ്വലിച്ചിട്ടും തീ എന്നെ പൊള്ളിച്ചില്ല.",
        "0.163": "എന്റെ ഹൃദയം സന്തോഷം നിറഞ്ഞു, സുഗന്ധമുള്ള കാറ്റ് വീശി. വ്യക്തമായ അർത്ഥമുള്ള ആ ശകുനങ്ങളാലും, വലിയ പുണ്യകാരണങ്ങളാലും,",
        "0.164": "അർത്ഥം വ്യക്തമായ മഹർഷിമാരുടെ വാക്കുകളാലും ഞാൻ ഹൃദയത്തിൽ സന്തോഷിച്ചു. ഞാൻ വീണ്ടും വൈദേഹിയെ കണ്ടു; അവളിൽനിന്ന് വീണ്ടും യാത്രാനുമതി ലഭിച്ചു.",
        "0.165": "പിന്നെ അവിടെ അരിഷ്ടപർവ്വതത്തിൽ കയറി, നിങ്ങളെ എല്ലാവരെയും കാണാനുള്ള ആഗ്രഹത്തോടെ ഞാൻ മടക്കച്ചാട്ടം തുടങ്ങി.",
        "0.166": "പിന്നെ കാറ്റ്, ചന്ദ്രൻ, സൂര്യൻ, സിദ്ധന്മാർ, ഗന്ധർവ്വന്മാർ എന്നിവർ സഞ്ചരിക്കുന്ന വഴിയിലൂടെ സഞ്ചരിച്ച്, ഇവിടെ ഞാൻ നിങ്ങളെ കണ്ടു.",
        "0.167": "രാഘവന്റെ കൃപയാലും നിങ്ങളുടെ സ്വന്തം ശക്തിയാലും സുഗ്രീവന്റെ ദൗത്യത്തിനുവേണ്ടി എല്ലാം ഞാൻ നിറവേറ്റി.",
        "0.168": "അവിടെ ഇതെല്ലാം ചെയ്യേണ്ടതുപോലെ ഞാൻ നിർവ്വഹിച്ചു; ഇനി ചെയ്യാത്തതായി എന്തെങ്കിലും ശേഷിക്കുന്നുവെങ്കിൽ, അതെല്ലാം ഇപ്പോൾ ചെയ്യപ്പെടട്ടെ.\"",
        "0.169": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തിയെട്ടാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "ജാംബവാന്റെ അഭ്യർത്ഥനപ്രകാരം ഹനുമാൻ തന്റെ യാത്രയുടെ മുഴുവൻ വിവരണവും നൽകുന്നു: സമുദ്രം കടന്നത്, ലങ്കയിലെ അന്വേഷണം, സീതയെ കണ്ടെത്തിയത്, യുദ്ധം, തന്റെ പിടിയിലാകൽ, നഗരം ചുട്ടെരിച്ചത് എന്നിവ."
    },
    "sundarakanda-59": {
      "verses": {
        "0.0": "ഇതെല്ലാം വിവരിച്ചശേഷം വായുപുത്രനായ ഹനുമാൻ കൂടുതൽ സംസാരിച്ചു:",
        "0.1": "\"രാഘവന്റെ പ്രയത്നവും സുഗ്രീവന്റെ ഉത്സാഹവും ഫലിച്ചിരിക്കുന്നു; സീതയുടെ പുണ്യം കണ്ടെത്തിയതിനാൽ എന്റെ ഹൃദയവും സന്തോഷിക്കുന്നു.",
        "0.2": "വാനരശ്രേഷ്ഠന്മാരേ, ശ്രേഷ്ഠയായ സീതയുടെ പുണ്യം അങ്ങനെയുള്ളതാണ്: തപസ്സുകൊണ്ട് അവൾക്ക് ലോകങ്ങളെ താങ്ങിനിർത്താനും, കോപിച്ചാൽ അവയെ ദഹിപ്പിക്കാനും കഴിയും.",
        "0.3": "രാക്ഷസരാജാവായ രാവണൻ അതിശക്തനായിരിക്കണം; അവൻ അവളെ തൊട്ടപ്പോൾ, അവളുടെ തപസ്സുകൊണ്ട് അവന്റെ ശരീരം നശിച്ചില്ലല്ലോ.",
        "0.4": "കൈകൊണ്ട് തൊട്ട ഒരു അഗ്നിനാളവും, കോപം ഉണർന്ന ജനകപുത്രിക്ക് ചെയ്യാൻ കഴിയുന്നതുപോലെ ചെയ്യുകയില്ല.",
        "0.5": "ജാംബവാന്റെയും നിങ്ങളായ മഹാവാനരന്മാരുടെയും അനുമതിയോടെ പറയട്ടെ: ദൗത്യം ഈ ഘട്ടത്തിലെത്തി, നിങ്ങളെ അറിയിച്ചിരിക്കുന്നതിനാൽ, ആ രണ്ടു രാജകുമാരന്മാരെ കാണാൻ നമ്മൾ വൈദേഹിയോടൊപ്പം പോകുന്നതാണ് ശരി.",
        "0.6": "ഞാൻ ഒരാൾ മാത്രം മതി, ബലത്താൽ ആ ലങ്കാനഗരത്തെയും രാക്ഷസസൈന്യത്തെയും, മഹാനായ രാവണനെയും നശിപ്പിക്കാൻ;",
        "0.7": "നിങ്ങൾ, വീരന്മാരും ശക്തരും ഉറച്ച മനസ്സുള്ളവരും ആയുധവിദ്യയിൽ നിപുണരും വിജയത്തിന് കഴിവും ആഗ്രഹവുമുള്ളവരുമായ വാനരന്മാർ, ഒന്നിച്ചുണ്ടെങ്കിൽ പിന്നെ പറയേണ്ടതില്ലല്ലോ!",
        "0.8": "യുദ്ധത്തിൽ സൈന്യത്തോടും മുൻനിരപ്പടയോടുമൊപ്പം, പുത്രന്മാരോടും സഹോദരന്മാരോടുമൊപ്പം ഞാൻ രാവണനെ വധിക്കും.",
        "0.9": "ഇന്ദ്രജിത്തിന്റെ ബ്രഹ്മാസ്ത്രം, രൗദ്രാസ്ത്രം, വായവ്യാസ്ത്രം, വാരുണാസ്ത്രം എന്നിവ യുദ്ധത്തിൽ നോക്കാൻ പോലും പ്രയാസമാണെങ്കിലും, ഞാൻ അവയെ എതിർത്ത് രാക്ഷസരെ ചിതറിക്കും.",
        "0.10": "നിങ്ങളുടെ അനുമതിയോടെ എന്റെ വീര്യം അവനെ തടയും. എനിക്ക് തുല്യനില്ലാത്ത ഞാൻ എറിയുന്ന പാറകളുടെ നിലയ്ക്കാത്ത വർഷം",
        "0.11": "യുദ്ധത്തിൽ ദേവന്മാരെപ്പോലും വധിക്കാൻ കഴിയും; ആ രാത്രിസഞ്ചാരികളെക്കുറിച്ച് പറയേണ്ടതില്ല. നിങ്ങളുടെ അനുമതി ഇല്ലാത്തതുകൊണ്ടുമാത്രമാണ് എന്റെ വീര്യം എന്നെ പിടിച്ചുനിർത്തുന്നത്.",
        "0.12": "സമുദ്രം തീരം വിട്ടുകയറിയാലും, മന്ദരപർവ്വതം ഇളകിയാലും, യുദ്ധത്തിൽ ഒരു ശത്രുസൈന്യത്തിനും ജാംബവാനെ വിറപ്പിക്കാനാവില്ല.",
        "0.13": "വാലിയുടെ പുത്രനായ വീരവാനരൻ ഒറ്റയ്ക്കുതന്നെ രാക്ഷസസൈന്യങ്ങളെയും മുതിർന്ന രാക്ഷസരെയും നശിപ്പിക്കാൻ മതിയായവനാണ്.",
        "0.14": "മഹാവാനരനായ നീലന്റെ തുടകളുടെ ബലംകൊണ്ട് മന്ദരപർവ്വതംപോലും തകർന്നുപോകും; യുദ്ധത്തിലെ രാക്ഷസരെക്കുറിച്ച് പറയേണ്ടതില്ലല്ലോ.",
        "0.15": "ദേവന്മാർ, അസുരന്മാർ, യക്ഷന്മാർ, ഗന്ധർവ്വന്മാർ, സർപ്പങ്ങൾ, പക്ഷികൾ എന്നിവരിൽ ആർക്കാണ് മൈന്ദനെയോ ദ്വിവിദനെയോ എതിർത്തുനിൽക്കാൻ കഴിയുക എന്ന് പറയൂ.",
        "0.16": "അശ്വിനികുമാരന്മാരുടെ പുത്രന്മാരായ ഈ രണ്ടു വാനരശ്രേഷ്ഠന്മാർ അതിവേഗമുള്ളവരാണ്; യുദ്ധക്കളത്തിൽ അവരെ എതിർക്കാൻ കഴിയുന്ന ആരെയും ഞാൻ കാണുന്നില്ല.",
        "0.17": "ഞാൻ ഒറ്റയ്ക്ക് ലങ്കയെ പ്രഹരിച്ചു; നഗരം ചാമ്പലാക്കി. എല്ലാ രാജവീഥികളിലും ഞാൻ എന്റെ പേര് വിളിച്ചുപറഞ്ഞു:",
        "0.18": "\"അതിശക്തനായ രാമനും മഹാവീരനായ ലക്ഷ്മണനും ജയം! രാഘവന്റെ സംരക്ഷണയിലുള്ള സുഗ്രീവരാജാവിന് ജയം!",
        "0.19": "കോസലരാജാവിന്റെ ദാസനും വായുവിൽ ജനിച്ചവനും ഹനുമാൻ എന്ന് പേരുള്ളവനുമാണ് ഞാൻ\" എന്ന് ഞാൻ എല്ലായിടത്തും ഇങ്ങനെ വിളിച്ചുപറഞ്ഞു.",
        "0.20": "ദുഷ്ടനായ രാവണന്റെ അശോകവനത്തിന്റെ നടുവിൽ, ഒരു ശിംശപാവൃക്ഷത്തിന്റെ ചുവട്ടിൽ, പുണ്യവതിയായ ആ സ്ത്രീ ദയനീയാവസ്ഥയിൽ ഇരിക്കുന്നു,",
        "0.21": "രാക്ഷസിമാർ ചുറ്റിനിൽക്കെ, ദുഃഖവും വേദനയും കൊണ്ട് ക്ഷീണിച്ച്, മേഘനിര മറച്ച ചന്ദ്രക്കലപോലെ പ്രകാശമറ്റവളായി.",
        "0.22": "ശക്തിയിൽ അഹങ്കരിക്കുന്ന രാവണനെ വൈദേഹി ഗൗനിക്കുന്നില്ല; മനോഹര അരക്കെട്ടുള്ള ജാനകി ഭർത്താവിനോട് ഭക്തിയുള്ളവളായി ഉറച്ചുനിൽക്കുന്നു.",
        "0.23": "ഐശ്വര്യവതിയായ വൈദേഹി മുഴുവൻ മനസ്സോടെ രാമനിൽ ഭക്തിയുള്ളവളാണ്; ഇന്ദ്രനിൽ പൗലോമിയുടെ മനസ്സുപോലെ, രാമനല്ലാതെ മറ്റാരിലും അവളുടെ മനസ്സ് ഉറച്ചിട്ടില്ല.",
        "0.24": "ആ ഒറ്റ വസ്ത്രം ധരിച്ച്, പൊടിപിടിച്ച്, വിനോദോദ്യാനത്തിൽ രാക്ഷസിമാർക്കിടയിൽ അവളെ ഞാൻ കണ്ടു; അവൾ ആവർത്തിച്ച് ഭീഷണിപ്പെടുത്തപ്പെട്ടുകൊണ്ടിരുന്നു.",
        "0.25": "ഭയങ്കര രാക്ഷസിമാരാൽ; ഒറ്റ ജടയണിഞ്ഞ്, ദയനീയയായി, ഭർത്താവിനെക്കുറിച്ചുള്ള ചിന്തയിൽ മുഴുകി,",
        "0.26": "നിലത്ത് ഉറങ്ങി, മഞ്ഞുകാലാരംഭത്തിൽ വാടിയ താമരച്ചെടിപോലെ വിളറിയവളായി; രാവണനിൽനിന്ന് മുഖം തിരിച്ച്, മരിക്കാൻ ഉറച്ചിരിക്കുന്നു.",
        "0.27": "പ്രയാസപ്പെട്ടാണ് മാൻമിഴിയായവൾ എന്നിൽ വിശ്വാസം നേടിയത്; പിന്നെ ഞാൻ അവളോട് സംസാരിച്ച്, കാര്യം മുഴുവൻ വിശദീകരിച്ചു.",
        "0.28": "രാമനും സുഗ്രീവനും തമ്മിലുള്ള സൗഹൃദം കേട്ടപ്പോൾ അവൾ സന്തോഷിച്ചു. അവളുടെ നടപ്പ് അച്ചടക്കമുള്ളത്; ഭർത്താവിനോടുള്ള ഭക്തി പരമമാണ്.",
        "0.29": "ആ മഹാത്മാവായ സ്ത്രീ പത്തുകഴുത്തുള്ളവനെ സ്വയം നശിപ്പിക്കാത്തത്, രാമൻ അവന്റെ മരണത്തിന്റെ ഉപകരണമാകാൻ വേണ്ടി മാത്രമാണ്.",
        "0.30": "സ്വഭാവത്താൽ മെലിഞ്ഞവൾ, അദ്ദേഹത്തിൽനിന്നുള്ള വേർപാടിനാൽ കൂടുതൽ ക്ഷീണിച്ചിരിക്കുന്നു; വിലക്കപ്പെട്ട ചന്ദ്രദിനമായ പ്രതിപദത്തിൽ പഠിക്കുന്നവന്റെ വിദ്യപോലെ.",
        "0.31": "ഇങ്ങനെ ശ്രേഷ്ഠയായ സീത ദുഃഖത്തിൽ മുഴുകി ജീവിക്കുന്നു. ഇവിടെ ചെയ്യേണ്ട പ്രതിവിധി എന്തായാലും, അതെല്ലാം ക്രമീകരിക്കൂ.\"",
        "0.32": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തിയൊമ്പതാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "ഹനുമാൻ സീതയുടെ പരിശുദ്ധിയെ പ്രശംസിക്കുന്നു; കോപംകൊണ്ട് രാവണനെ ദഹിപ്പിക്കാൻ അവൾക്ക് കഴിയുമെന്നും, വാനരവീരന്മാർക്ക് ലങ്കയെ സ്വയം നശിപ്പിക്കാൻ ശക്തിയുണ്ടെന്നും പറയുന്നു. അശോകവനത്തിൽ സീത അനുഭവിക്കുന്ന ദുരിതം വിവരിച്ച്, ഇനി എന്തുചെയ്യണമെന്ന് തീരുമാനിക്കാൻ അവൻ അവരോട് ആവശ്യപ്പെടുന്നു."
    },
    "sundarakanda-60": {
      "verses": {
        "0.0": "അവന്റെ വാക്കുകൾ കേട്ട് വാലിയുടെ പുത്രൻ പറഞ്ഞു: \"ഈ രണ്ടു വാനരന്മാരും, അശ്വിനീദേവന്മാരുടെ പുത്രന്മാർ, വലിയ വേഗവും ശക്തിയുമുള്ളവരാണ്.",
        "0.1": "ബ്രഹ്മാവിന്റെ വരത്താൽ ആഹ്ലാദിച്ച് അവർ അതിരറ്റ് അഹങ്കാരികളായിരിക്കുന്നു; അശ്വിനീദേവന്മാരെ ആദരിക്കാൻ, ലോകങ്ങളുടെ പിതാമഹനായ ബ്രഹ്മാവ്",
        "0.2": "പണ്ടുതന്നെ എല്ലാവർക്കും അജയ്യരാകുക എന്ന അതുല്യമായ വരം അവർക്ക് നൽകി. ആ വരത്തിലെ അഹങ്കാരത്താൽ ലഹരിപിടിച്ച ഈ രണ്ടു വീരന്മാർ ഒരിക്കൽ ഒരു വലിയ സൈന്യത്തെ തകർത്തു,",
        "0.3": "ദേവന്മാരുടെ അമൃത് കുടിച്ചു; ശക്തരായ അവർ തന്നെ. കോപിച്ചാൽ, കുതിരകളോടും രഥങ്ങളോടും ആനകളോടും കൂടി ഈ രണ്ടുപേർ മാത്രം",
        "0.4": "ലങ്കയെ നശിപ്പിക്കാൻ കഴിയും; മറ്റ് വാനരന്മാർ മാറിനിൽക്കട്ടെ. ഞാൻ ഒറ്റയ്ക്ക് തന്നെ രാക്ഷസസൈന്യങ്ങളോടുകൂടിയ ആ ലങ്കാനഗരം നശിപ്പിക്കാൻ മതി,",
        "0.5": "ബലത്താൽ, മഹാനായ രാവണനെയും; നിങ്ങളെപ്പോലെ ശക്തരും ഉറച്ച മനസ്സുള്ളവരുമായ വീരന്മാരോടൊപ്പമാകുമ്പോൾ പിന്നെ പറയേണ്ടതുണ്ടോ?",
        "0.6": "ആയുധവിദ്യയിൽ നിപുണരും, വിജയത്തിന് കഴിവും ആഗ്രഹവുമുള്ള നിങ്ങളെപ്പോലുള്ള വാനരന്മാരേ. ലങ്ക കത്തിയത് വായുപുത്രന്റെ ശക്തിയാൽ മാത്രമാണെന്ന് ഞങ്ങൾ കേട്ടിട്ടുണ്ട്.",
        "0.7": "\"ദേവിയെ കണ്ടു, പക്ഷേ തിരികെ കൊണ്ടുവന്നില്ല\" എന്ന് അവിടെ റിപ്പോർട്ട് ചെയ്യുന്നത്, പ്രസിദ്ധമായ വീര്യമുള്ള നിങ്ങൾക്ക് യോജിച്ചതായി എനിക്ക് തോന്നുന്നില്ല.",
        "0.8": "വാനരശ്രേഷ്ഠാ, ലോകങ്ങളിൽ, ദേവന്മാരിലും ദൈത്യന്മാരിലും, ചാട്ടത്തിലോ വീര്യത്തിലോ നിങ്ങളിൽ ആർക്കും തുല്യരില്ല.",
        "0.9": "രാക്ഷസക്കൂട്ടങ്ങളോടുകൂടിയ ലങ്കയെ കീഴടക്കി, യുദ്ധത്തിൽ രാവണനെ വധിച്ച്, സീതയെയും കൊണ്ട് നമ്മുടെ ലക്ഷ്യം നിറവേറി ഹൃദയം സന്തോഷിച്ച് മടങ്ങാം.",
        "0.10": "ഹനുമാൻ ഇതിനകം ഒരുപാട് രാക്ഷസവീരന്മാരെ വധിച്ചുകഴിഞ്ഞു; ഇനി ഇവിടെ എന്തുചെയ്യാനുണ്ട്? ജാനകിയെയും കൊണ്ട് നമുക്ക് പോകാം.",
        "0.11": "ജനകപുത്രിയെ രാമന്റെയും ലക്ഷ്മണന്റെയും അടുത്ത് എത്തിക്കാം. വെറുതെ മറ്റ് വാനരന്മാരെയും അവരുടെ നേതാക്കളെയും ബുദ്ധിമുട്ടിക്കുന്നതെന്തിന്?",
        "0.12": "ഞങ്ങൾതന്നെ പോയി, ആ മുൻനിര രാക്ഷസരെ വധിച്ച്, പിന്നെ രാഘവനെയും സുഗ്രീവനെയും ലക്ഷ്മണനെയും കാണാൻ പോകാം.\"",
        "0.13": "ഇങ്ങനെ ഉറച്ച തീരുമാനമെടുത്ത അവനോട്, ശരി എന്തെന്ന് അറിയുന്ന വാനരശ്രേഷ്ഠനായ ജാംബവാൻ, വലിയ വാത്സല്യത്തോടെ ഈ അർത്ഥവത്തായ വാക്കുകൾ പറഞ്ഞു:",
        "0.14": "\"ജ്ഞാനിയായ മഹാവാനരാ, നീ നിർദ്ദേശിക്കുന്നത് ശരിയായ മാർഗ്ഗമല്ല. ശ്രേഷ്ഠമായ തെക്കൻ ദിശ അന്വേഷിക്കാനാണ് ഞങ്ങൾക്ക് കല്പന ലഭിച്ചത്,",
        "0.15": "അവളെ തിരികെ കൊണ്ടുവരാനല്ല; വാനരരാജാവിനോ ജ്ഞാനിയായ രാമനോ അതിന് അനുമതിയില്ല. സീതയെ ഏതെങ്കിലും വിധത്തിൽ ഞങ്ങൾ തിരികെ നേടുന്നത് അവൻ അംഗീകരിക്കുകയുമില്ല.",
        "0.16": "രാജാക്കന്മാരിൽ വ്യാഘ്രമായ രാഘവൻ, തന്റെ വംശം പ്രഖ്യാപിച്ചുകൊണ്ട്, സീതയെ തിരികെ നേടുമെന്ന് എല്ലാവരുടെയും മുന്നിൽ സ്വയം പ്രതിജ്ഞയെടുത്തിരിക്കുന്നു.",
        "0.17": "വാനരപ്രമുഖരുടെ മുന്നിൽ അദ്ദേഹത്തിന്റെ വാക്ക് അസത്യമാക്കാൻ അദ്ദേഹത്തിന് കഴിയുമോ? എങ്കിൽ നമ്മൾ ചെയ്തതെല്ലാം വ്യർത്ഥമാകും; അദ്ദേഹം സന്തുഷ്ടനാകുകയുമില്ല.",
        "0.18": "വാനരപ്രമുഖരേ, നമ്മുടെ വീര്യപ്രകടനവും നിഷ്ഫലമാകും. അതിനാൽ നമുക്കെല്ലാവർക്കും രാമലക്ഷ്മണന്മാരുള്ളിടത്തേക്കും തേജസ്വിയായ സുഗ്രീവനുള്ളിടത്തേക്കും പോയി ഈ ദൗത്യം റിപ്പോർട്ട് ചെയ്യാം.\"",
        "0.19": "\"രാജകുമാരാ, നിന്റെ ഈ അഭിപ്രായം നിനക്ക് തോന്നുന്നതുപോലെ നമുക്ക് അയോഗ്യമല്ല; പക്ഷേ രാമന്റെ മനസ്സ് ദൗത്യത്തിൽ എങ്ങനെ ഉറച്ചിരിക്കുന്നു എന്ന രീതിയിൽ ദൗത്യത്തിന്റെ വിജയം നീ നോക്കണം.\"",
        "0.20": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപതാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "അംഗദൻ, ലങ്കയെ വാനരന്മാർതന്നെ ആക്രമിച്ച് രാവണനെ വധിച്ച് സീതയെ തിരികെ കൊണ്ടുവരാമെന്ന് നിർദ്ദേശിക്കുന്നു. ജാംബവാൻ അവനെ തടയുന്നു: അവർക്ക് നൽകിയ നിർദ്ദേശം അന്വേഷിക്കാൻ മാത്രമായിരുന്നു; സീതയെ സ്വയം നേടുമെന്ന് രാമൻ പ്രതിജ്ഞയെടുത്തിട്ടുണ്ട്."
    },
    "sundarakanda-61": {
      "verses": {
        "0.0": "അപ്പോൾ അംഗദന്റെ നേതൃത്വത്തിലുള്ള വനവാസികളായ വീരന്മാരും മഹാവാനരനായ ഹനുമാനും ജാംബവാന്റെ വാക്കുകൾ സ്വീകരിച്ചു.",
        "0.1": "പിന്നെ സന്തോഷം നിറഞ്ഞ കാളകളെപ്പോലുള്ള വാനരന്മാരെല്ലാം, വായുപുത്രൻ മുന്നിൽ നിൽക്കെ, മഹേന്ദ്രപർവ്വതശിഖരത്തിൽനിന്ന് കുതിച്ചുയർന്ന് പറന്നു.",
        "0.2": "മേരുവും മന്ദരവും പോലെ, മദയാനകൾപോലെ, ശരീരം വലുതും ശക്തവുമായ അവർ ആകാശം മറയ്ക്കുന്നതുപോലെ തോന്നി.",
        "0.3": "എല്ലാ ജീവികളും ആദരിക്കുന്ന, ശക്തനും വേഗവാനും ആത്മനിയന്ത്രണമുള്ളവനുമായ ഹനുമാനിൽ അവർ കണ്ണുകൾ ഉറപ്പിച്ചു; അവനെ നോട്ടംകൊണ്ട് വഹിക്കുന്നതുപോലെ.",
        "0.4": "രാഘവന്റെ ലക്ഷ്യം നിറവേറ്റാനും പരമമായ യശസ്സ് നേടാനും ഉറച്ചവരായി, ദൗത്യത്തിന്റെ വിജയത്തിൽ അവർ ആഹ്ലാദിച്ചു; അവരുടെ ലക്ഷ്യം പൂർത്തിയായിരുന്നു.",
        "0.5": "നല്ല വാർത്ത അറിയിക്കാൻ എല്ലാവരും ആഗ്രഹിച്ചു; യുദ്ധത്തിന്റെ സാധ്യതയിൽ എല്ലാവരും ആഹ്ലാദിച്ചു; ഉന്നതമനസ്കരായ അവർ എല്ലാവരും രാമനുവേണ്ടി പ്രതികാരം ചെയ്യാൻ ഉറച്ചു.",
        "0.6": "ആകാശത്തേക്ക് കുതിച്ചുചാടി പറന്ന്, ആ വനവാസികൾ നന്ദനവനത്തിന് സമാനമായ, എണ്ണമറ്റ ആയിരക്കണക്കിന് മരങ്ങളുള്ള ഒരു വനത്തിലെത്തി.",
        "0.7": "അത് മധുവനം എന്ന് വിളിക്കപ്പെടുന്ന വനമായിരുന്നു; സുഗ്രീവൻ ശ്രദ്ധയോടെ കാത്തുസൂക്ഷിച്ചത്; എല്ലാ ജീവികൾക്കും അജയ്യവും എല്ലാവർക്കും ആനന്ദകരവുമായത്.",
        "0.8": "വാനരശ്രേഷ്ഠനും മഹാത്മാവുമായ സുഗ്രീവന്റെ മാതുലനായ മഹാവീരൻ ദധിമുഖൻ എന്ന വാനരനായിരുന്നു അത് എപ്പോഴും കാത്തിരുന്നത്.",
        "0.9": "വാനരരാജാവിന് ഹൃദയത്തോട് പ്രിയപ്പെട്ട ആ മഹാവനത്തിൽ എത്തിയപ്പോൾ വാനരന്മാർ ആവേശത്താൽ ഭ്രാന്തരായി.",
        "0.10": "മഹത്തായ മധുവനം കണ്ട്, തേൻനിറമുള്ള സന്തുഷ്ടരായ വാനരന്മാർ രാജകുമാരനോട് തേൻ ചോദിച്ചു.",
        "0.11": "ജാംബവാന്റെ നേതൃത്വത്തിലുള്ള മുതിർന്ന വാനരന്മാരുമായി ആലോചിച്ചശേഷം, രാജകുമാരൻ തേൻ ആസ്വദിക്കാൻ അവർക്ക് അനുമതി നൽകി.",
        "0.12": "ജ്ഞാനിയായ വാലിപുത്രനായ രാജകുമാരന്റെ അനുമതി ലഭിച്ച വാനരന്മാർ, വണ്ടുകൾ മൂളുന്ന മരങ്ങളിൽ ഇരമ്പിക്കയറി.",
        "0.13": "സുഗന്ധമുള്ള വേരുകളും പഴങ്ങളും ഭക്ഷിച്ച്, അവരെല്ലാം ആനന്ദഭരിതരായി, ലഹരിയാൽ ഉന്മത്തരായി.",
        "0.14": "അനുമതി ലഭിച്ചതിനാൽ വനവാസികൾ ആഹ്ലാദിച്ചു; ആ സന്തോഷത്തിൽ അവർ ഇവിടെയും അവിടെയും നൃത്തം ചെയ്തു.",
        "0.15": "ചിലർ പാടി, ചിലർ ചിരിച്ചു, ചിലർ നൃത്തം ചെയ്തു, ചിലർ വണങ്ങി; ചിലർ വീണു, ചിലർ അലഞ്ഞുനടന്നു, ചിലർ ചാടി, ചിലർ പുലമ്പി.",
        "0.16": "ചിലർ പരസ്പരം ചാരിനിന്നു, ചിലർ പരസ്പരം കലഹിച്ചു; ചിലർ മരത്തിൽനിന്ന് മരത്തിലേക്ക് ഓടി, ചിലർ മരച്ചില്ലകളിൽനിന്ന് നിലത്തേക്ക് വീണു.",
        "0.17": "ചിലർ ഊർജ്ജം തിളച്ചുപൊങ്ങി നിലത്തുനിന്ന് വലിയ മരങ്ങളുടെ മുകളിലേക്ക് ചാടി; പാടുന്ന ഒരാളുടെ അടുത്തേക്ക് ചിരിച്ചുകൊണ്ട് മറ്റൊരാൾ വന്നു; ചിരിക്കുന്ന ഒരാളുടെ അടുത്തേക്ക് കരഞ്ഞുകൊണ്ട് മറ്റൊരാൾ വന്നു.",
        "0.18": "കുത്തുന്ന മറ്റൊരാളോട് ഒരാൾ ആക്രോശിച്ചുകൊണ്ട് വന്നു; വാനരസംഘം മുഴുവൻ ബഹളത്തിലായി. അവിടെ ലഹരിപിടിക്കാത്തവനോ അഹങ്കാരംകൊണ്ട് ഉന്മത്തനാകാത്തവനോ ആരുമുണ്ടായിരുന്നില്ല.",
        "0.19": "അപ്പോൾ തോട്ടം തിന്നുതീർക്കപ്പെടുന്നതും മരങ്ങൾ ഇലകളും പൂക്കളും നഷ്ടപ്പെട്ട് നഗ്നമാകുന്നതും കണ്ട്, ദധിമുഖൻ എന്ന വാനരൻ ആ വാനരന്മാരെ കോപത്തോടെ തടയാൻ ശ്രമിച്ചു.",
        "0.20": "ആ അരാജകരായ വാനരന്മാരാൽ അധിക്ഷേപിക്കപ്പെട്ട വൃദ്ധനായ വാനരവീരൻ, തോട്ടത്തിന്റെ സംരക്ഷകൻ, ഊർജ്ജസ്വലതയാൽ ഉഗ്രനായി, അവരിൽനിന്ന് തോട്ടം സംരക്ഷിക്കാൻ വീണ്ടും ഉറച്ചു.",
        "0.21": "ചിലരോട് ഭയമില്ലാതെ കഠിനവാക്കുകൾ പറഞ്ഞു, ചിലരെ കൈപ്പത്തികൊണ്ട് ശക്തിയായി അടിച്ചു, ചിലരോട് ഏറ്റുമുട്ടി, മറ്റു ചിലരെ ആശ്വാസവാക്കുകളാൽ സമീപിച്ചു.",
        "0.22": "എന്നാൽ ലഹരിയിൽ കുതിപ്പ് തടയാനാവാത്ത അവർ, അവൻ ബലമായി തടഞ്ഞപ്പോൾ, ഒന്നിച്ച് അവന്റെ മേൽ വീണു; ആക്രമണത്തെ ഭയമില്ലാതെ, ഒരു തെറ്റും ഗണിക്കാതെ അവനെ വലിച്ചിഴച്ചു.",
        "0.23": "നഖംകൊണ്ട് മാന്തിയും പല്ലുകൊണ്ട് കടിച്ചും, കൈകാലുകൾകൊണ്ട് ഇടിച്ചും, ഭ്രാന്തമായ ആവേശത്തിൽ വാനരന്മാർ ആ വാനരനെ ഏറെക്കുറെ കൊന്നുകളഞ്ഞു; വലിയ തോട്ടം അവർ നഗ്നമാക്കി.",
        "0.24": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപത്തൊന്നാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "വാനരന്മാർ സന്തോഷത്തോടെ കിഷ്കിന്ധയിലേക്ക് പുറപ്പെട്ട്, സുഗ്രീവന്റെ സംരക്ഷണയിലുള്ള മധുവനത്തിലെത്തുന്നു. അംഗദന്റെ അനുമതിയോടെ അവർ തേൻ കുടിച്ച് ആഘോഷിക്കുന്നു; കാവൽക്കാരനായ ദധിമുഖന്റെ ആളുകളെ അവർ കീഴടക്കുന്നു."
    },
    "sundarakanda-62": {
      "verses": {
        "0.0": "വാനരശ്രേഷ്ഠനും വാനരപ്രമുഖനുമായ ഹനുമാൻ അവരോട് പറഞ്ഞു: \"വാനരന്മാരേ, മനസ്സമാധാനത്തോടെ തേൻ ആസ്വദിച്ചുകൊള്ളൂ.",
        "0.1": "നിങ്ങളുടെ വഴി തടസ്സപ്പെടുത്തുന്നവരെ ഞാൻ അകറ്റിനിർത്തും.\" ഹനുമാന്റെ വാക്കുകൾ കേട്ട്, വാനരപ്രമുഖനായ അംഗദൻ",
        "0.2": "ദയാപൂർണ്ണമായ ഹൃദയത്തോടെ മറുപടി പറഞ്ഞു: \"വാനരന്മാർ തേൻ കുടിക്കട്ടെ. ദൗത്യം നിറവേറ്റിയ ഹനുമാന്റെ വാക്ക് ഞാൻ തീർച്ചയായും അനുസരിക്കണം,",
        "0.3": "ചെയ്യാൻ പാടില്ലാത്ത കാര്യമായാലും പോലും; ഇതുപോലുള്ള കാര്യത്തിൽ പറയേണ്ടതുണ്ടോ!\" അംഗദന്റെ വായിൽനിന്ന് ഈ വാക്കുകൾ കേട്ട്, പ്രധാനവാനരന്മാർ",
        "0.4": "സന്തോഷിച്ച്, \"നന്നായി, നന്നായി!\" എന്ന് വിളിച്ച് അവനെ പ്രശംസിച്ചു. കാളയെപ്പോലുള്ള അംഗദനെ ആദരിച്ചശേഷം, എല്ലാ വാനരന്മാരും",
        "0.5": "പ്രളയജലം മരത്തിലേക്ക് ഒഴുകിക്കയറുന്ന നദിപോലെ മധുവനത്തിലേക്ക് കുതിച്ചു. മധുവനത്തിൽ പ്രവേശിച്ച്, അവർ ബലമായി കാവൽക്കാരെ കീഴടക്കി,",
        "0.6": "അനുമതിയാൽ ധൈര്യം ലഭിച്ച്, മൈഥിലിയെപ്പറ്റി കണ്ടും കേട്ടും അറിഞ്ഞവരായി, അവരെല്ലാം തേൻ കുടിച്ചു, രസമുള്ള പഴങ്ങൾ എടുത്തു.",
        "0.7": "പിന്നെ ചാടിയെഴുന്നേറ്റ്, മധുവനത്തിൽ മുഴുകിയിരുന്ന അവർ, നൂറുകണക്കിന് വന്ന വനപാലകരെ അടിച്ചു.",
        "0.8": "ചില വാനരന്മാർ ഒരു ദ്രോണം അളവുള്ള തേൻകൂടുകൾ കൈകളിൽ ചേർത്തുപിടിച്ച്, അവിടെ സന്തോഷത്തോടെ കൂട്ടമായി കുടിച്ചു.",
        "0.9": "ചിലർ ഒന്നിച്ച് കാവൽക്കാരെ അടിച്ചു, മറ്റുചിലർ തിന്നു; തേൻനിറമുള്ള ചിലർ കുടിച്ചശേഷം തേൻ വലിച്ചെറിഞ്ഞു.",
        "0.10": "ചിലർ ആവേശംകൊണ്ട് ഭ്രാന്തരായി, തേൻകൂടിലെ മെഴുക് പരസ്പരം എറിഞ്ഞു; മറ്റുചിലർ മരച്ചുവട്ടിൽ ചില്ലകളിൽ പിടിച്ചിരുന്നു.",
        "0.11": "ലഹരിയാൽ പൂർണ്ണമായി കീഴടക്കപ്പെട്ട ചിലർ ഇലകൾ വിരിച്ച് കിടന്നു; തേൻകൊണ്ട് ഉന്മത്തരായ വാനരന്മാർ ആനന്ദിച്ചു;",
        "0.12": "അവർ പരസ്പരം തള്ളി, മറ്റുചിലർ ഇടറി വീണു; ചിലർ ആർപ്പുവിളിച്ചു, ചിലർ ആനന്ദത്താൽ കുറുകി.",
        "0.13": "തേൻ കുടിച്ച് ലഹരിയിലായ ചില വാനരന്മാർ നിലത്ത് ഉറങ്ങി; ധൈര്യശാലികളായ ചിലർ ചിരിച്ചു, മറ്റുചിലർ അതിന് നേർവിപരീതമായി ചെയ്തു.",
        "0.14": "ചിലർ ഒന്ന് ചെയ്തിട്ട് മറ്റൊന്ന് പറഞ്ഞു, ചിലർ ഒന്നിനെ മറ്റൊന്നായി തെറ്റിദ്ധരിച്ചു. അവിടെയുണ്ടായിരുന്ന തേൻകാവൽക്കാർ, ദധിമുഖന്റെ ദാസന്മാർ,",
        "0.15": "ആ ഭയങ്കര വാനരന്മാരാൽ എല്ലാ ദിക്കുകളിലേക്കും ഓടിക്കപ്പെട്ടു; മുട്ടുകുത്തി വലിച്ചിഴക്കപ്പെട്ട്, ആകാശത്തേക്ക് എറിയപ്പെട്ടു.",
        "0.16": "വളരെ വിഷമിച്ച്, അവർ ദധിമുഖന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു: \"ഹനുമാൻ അനുവദിച്ചവർ മധുവനം ബലമായി കൊള്ളയടിച്ചിരിക്കുന്നു; ഞങ്ങളെ മുട്ടുകുത്തി വലിച്ചിഴച്ച് ആകാശത്തേക്ക് എറിഞ്ഞു.\"",
        "0.17": "അപ്പോൾ തോട്ടത്തിന്റെ വാനരസംരക്ഷകനായ ദധിമുഖൻ, മധുവനം നശിപ്പിക്കപ്പെട്ടു എന്ന് കേട്ട് കോപിച്ച്, ആ വാനരന്മാരെ ആശ്വസിപ്പിച്ചു:",
        "0.18": "\"വരൂ, വരൂ, ആ അഹങ്കാരികളായ വാനരന്മാരുടെ അടുത്തേക്ക് നമുക്ക് പോകാം; ഏറ്റവും മികച്ച തേൻ ആസ്വദിക്കുന്നതിൽനിന്ന് ഞാൻ അവരെ ബലമായി തടയും.\"",
        "0.19": "ദധിമുഖന്റെ വാക്കുകൾ കേട്ട്, ആ വീരവാനരന്മാർ അവനോടൊപ്പം മധുവനത്തിലേക്ക് ഒന്നിച്ച് തിരിച്ചുപോയി.",
        "0.20": "അവർക്കിടയിൽ, ഒരു വലിയ മരം മുറുകെ പിടിച്ച്, ദധിമുഖൻ വേഗത്തിൽ മുന്നോട്ട് കുതിച്ചു; അവനോടൊപ്പം ആ വാനരന്മാരെല്ലാവരും.",
        "0.21": "കോപത്തോടെ പാറകളും മരങ്ങളും വലിയ കല്ലുകളും എടുത്ത ആ വാനരന്മാർ, ആനപോലുള്ള വാനരന്മാരുടെ അടുത്തേക്ക് വന്നു.",
        "0.22": "ബലമായി അവരെ തടയാൻ ശ്രമിച്ചുകൊണ്ട്, വാനരന്മാർ ദേഷ്യത്താൽ ചുണ്ടുകടിച്ച്, വീണ്ടും വീണ്ടും ഭീഷണിപ്പെടുത്തി, അവരെ വളഞ്ഞു.",
        "0.23": "കോപിച്ച ദധിമുഖനെ കണ്ടപ്പോൾ, ഹനുമാന്റെ നേതൃത്വത്തിലുള്ള പ്രധാനവാനരന്മാർ വേഗത്തിൽ അവന്റെ നേരെ കുതിച്ചു.",
        "0.24": "കോപിഷ്ഠനായ അംഗദൻ, മരവുമായി മുന്നോട്ട് വന്ന ശക്തനും ബലവാനും വേഗവാനുമായ ദധിമുഖനെ രണ്ടു കൈകൊണ്ടും പിടികൂടി.",
        "0.25": "ലഹരിയാൽ കണ്ണുകാണാതെ, അവൻ തന്റെ ആദരണീയനായ മുതിർന്നവനായിരുന്നിട്ടും ദയ കാണിച്ചില്ല; വേഗത്തിൽ അവനെ നിലത്തേക്ക് ശക്തിയായി എറിഞ്ഞു.",
        "0.26": "കൈകളും തുടകളും മുഖവും മുറിവേറ്റ്, ആശയക്കുഴപ്പത്തിലായി രക്തത്തിൽ കുതിർന്ന ആ മഹാവീരൻ, വാനരകുഞ്ജരൻ, കുറച്ചുനേരം ബോധരഹിതനായി.",
        "0.27": "ഒരുവിധം ആ വാനരന്മാരാൽ മോചിപ്പിക്കപ്പെട്ട ആ വാനരശ്രേഷ്ഠൻ, ഏകാന്തമായ ഒരിടത്തേക്ക് പോയി, അവിടെ കൂടിയിരുന്ന സ്വന്തം ഭൃത്യന്മാരോട് സംസാരിച്ചു:",
        "0.28": "\"വരൂ, വരൂ, നമ്മുടെ യജമാനനായ, വിശാലകണ്ഠനായ വാനരൻ സുഗ്രീവൻ രാമനോടൊപ്പം താമസിക്കുന്നിടത്തേക്ക് പോകാം.",
        "0.29": "അംഗദന്റെ അപരാധമെല്ലാം നമുക്ക് രാജാവിനെ അറിയിക്കാം; അത് കേട്ടാൽ, കോപത്തോടെ അദ്ദേഹം വാനരന്മാരെ വധിക്കാൻ കല്പിക്കും.",
        "0.30": "ഈ മധുവനം മഹാത്മാവായ സുഗ്രീവന് പ്രിയപ്പെട്ടതാണ്; അത് അദ്ദേഹത്തിന്റെ പൈതൃകമായ ദിവ്യവനമാണ്, ദേവന്മാർക്കുപോലും പ്രവേശിക്കാൻ പ്രയാസമുള്ളത്.",
        "0.31": "തേനിനായി അത്യാഗ്രഹമുള്ള ഈ വാനരന്മാരെ, അവരുടെ ആയുസ്സ് തീർന്നവരായി, കൂട്ടുകാരോടൊപ്പം സുഗ്രീവൻ ശിക്ഷിച്ച് വധിക്കും.",
        "0.32": "രാജാവിന്റെ കല്പനയെ ധിക്കരിക്കുന്ന ഈ ദുഷ്ടന്മാർ മരണം അർഹിക്കുന്നു; ക്ഷോഭത്താൽ ജനിച്ച എന്റെ കോപം ഫലം കാണും.\"",
        "0.33": "കാവൽക്കാരോട് ഇത് പറഞ്ഞശേഷം, ശക്തനായ ദധിമുഖൻ പെട്ടെന്ന് ചാടിയെഴുന്നേറ്റ് അവരോടൊപ്പം പോയി.",
        "0.34": "കണ്ണിമവെട്ടുന്ന നേരംകൊണ്ട്, ആ വനവാസി, ആയിരം രശ്മികളുള്ള സൂര്യന്റെ പുത്രനായ ജ്ഞാനിയായ വാനരൻ സുഗ്രീവൻ നിൽക്കുന്നിടത്ത് എത്തി.",
        "0.35": "രാമനെയും ലക്ഷ്മണനെയും സുഗ്രീവനെയും കണ്ട്, അവൻ ആകാശത്തുനിന്ന് സമതലത്തിലേക്ക് ഇറങ്ങി.",
        "0.36": "ഇറങ്ങിയശേഷം, വാനരശ്രേഷ്ഠനും മഹാവീരനുമായ ദധിമുഖൻ, കാവൽക്കാരുടെ പരമാധിപനായി, ആ കാവൽക്കാരെല്ലാം ചുറ്റിനിൽക്കെ,",
        "0.37": "താഴ്ന്ന മുഖത്തോടെ, തലയ്ക്കുമേൽ കൂപ്പിയ കൈകളുമായി, സുഗ്രീവന്റെ പാദങ്ങളിൽ വേഗത്തിൽ തല ചേർത്തു.",
        "0.38": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപത്തിരണ്ടാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "ഹനുമാനും അംഗദനും വാനരന്മാരെ തേൻ ആസ്വദിക്കാൻ പ്രോത്സാഹിപ്പിക്കുന്നു. അവരെ തടയാൻ ശ്രമിച്ച ദധിമുഖൻ മർദ്ദിക്കപ്പെടുന്നു; അവൻ പരാതി പറയാൻ സുഗ്രീവന്റെ അടുത്തേക്ക് ധൃതിയിൽ പോകുന്നു."
    },
    "sundarakanda-63": {
      "verses": {
        "0.0": "പാദങ്ങൾക്കരികെ തല വെച്ച് വീണ വാനരനെ കണ്ട്, മനസ്സ് വിഷമിച്ച വാനരശ്രേഷ്ഠൻ ഇങ്ങനെ പറഞ്ഞു:",
        "0.1": "\"എഴുന്നേൽക്കൂ, എഴുന്നേൽക്കൂ! എന്തിനാണ് എന്റെ കാൽക്കൽ വീണത്? ഞാൻ നിനക്ക് അഭയം നൽകുന്നു; സത്യം മാത്രം പറയൂ.",
        "0.2": "എന്തിനാണ് ഈ പരിഭ്രമം? എന്റെ നന്മയ്ക്കായി നിനക്ക് പറയാനുള്ളതെല്ലാം പറയൂ. മധുവനത്തിൽ എല്ലാം സുഖമാണോ? ഞാൻ കേൾക്കാൻ ആഗ്രഹിക്കുന്നു, വാനരാ.\"",
        "0.3": "മഹാത്മാവായ സുഗ്രീവന്റെ ആശ്വാസവാക്കുകൾക്കുശേഷം, ജ്ഞാനിയായ ദധിമുഖൻ എഴുന്നേറ്റ് ഈ വാക്കുകൾ പറഞ്ഞു:",
        "0.4": "\"രാജാവേ, ഋക്ഷരാജാവോ, അങ്ങോ, വാലിയോ മുമ്പൊരിക്കലും തുറന്നുകൊടുക്കാത്ത ആ തോട്ടം വാനരന്മാർ നശിപ്പിച്ചിരിക്കുന്നു.",
        "0.5": "ഞാനും ഈ വനവാസികളും അവരെയെല്ലാം തടയാൻ ശ്രമിച്ചു; പക്ഷേ എന്നെ ഗൗനിക്കാതെ അവർ ആനന്ദത്തോടെ തിന്നുകയും കുടിക്കുകയും ചെയ്യുന്നു.",
        "0.6": "ഈ വനപാലകർ അവരുടെ ആക്രമണം തടയാൻ ശ്രമിച്ചപ്പോൾ, വനവാസികൾ, പ്രഭോ, എന്നെയും ഗൗനിക്കാതെ തിന്നുകൊണ്ടിരുന്നു.",
        "0.7": "ചിലർ ബാക്കിയുള്ളത് വലിച്ചെറിയുന്നു, മറ്റുചിലർ അത് തിന്നുന്നു; അവരെല്ലാം തടയപ്പെട്ടപ്പോൾ ഞങ്ങളെ കോപത്തോടെ നോക്കുന്നു.",
        "0.8": "ഈ കാവൽക്കാർ കൂടുതൽ കോപിച്ചപ്പോൾ, ഉഗ്രരായ വാനരപ്രമുഖന്മാർ അവരെ ആക്രമിച്ച് ആ തോട്ടത്തിൽനിന്ന് ഓടിച്ചു.",
        "0.9": "പിന്നെ, കോപംകൊണ്ട് കണ്ണുചുവന്ന ആ പല വീരവാനരന്മാർ ഈ വാനരപ്രമുഖന്മാരെ ആക്രമിച്ചു.",
        "0.10": "ചിലരെ കൈപ്പത്തികൊണ്ടും ചിലരെ മുട്ടുകൊണ്ടും അടിച്ചു; അവരെ ഇഷ്ടംപോലെ വലിച്ചിഴച്ച് ആകാശത്തേക്ക് എറിഞ്ഞു.",
        "0.11": "ഇങ്ങനെ ആ ധീരന്മാർ, അവരുടെ യജമാനനായ അങ്ങ് ഇവിടെ ഇരിക്കെ, അടിക്കപ്പെട്ടിരിക്കുന്നു; മുഴുവൻ മധുവനവും അവർ ഇഷ്ടംപോലെ തിന്നുതീർക്കുകയാണ്.\"",
        "0.12": "ഇത് പറയപ്പെടുമ്പോൾ, വാനരശ്രേഷ്ഠനായ സുഗ്രീവനോട്, ശത്രുവീരന്മാരെ വധിക്കുന്ന ജ്ഞാനിയായ ലക്ഷ്മണൻ ചോദിച്ചു:",
        "0.13": "\"രാജാവേ, എന്തിനാണ് ഈ തോട്ടത്തിന്റെ സൂക്ഷിപ്പുകാരനായ ഈ വാനരൻ ഇവിടെ വന്നത്? ഇത്ര ദുഃഖത്തോടെ ഇയാൾ എന്താണ് പറയുന്നത്?\"",
        "0.14": "മഹാത്മാവായ ലക്ഷ്മണൻ ഇങ്ങനെ ചോദിച്ചപ്പോൾ, വാക്കുകളിൽ നിപുണനായ സുഗ്രീവൻ ലക്ഷ്മണന് മറുപടി നൽകി:",
        "0.15": "\"ശ്രേഷ്ഠനായ ലക്ഷ്മണാ, അംഗദന്റെ നേതൃത്വത്തിലുള്ള വീരവാനരന്മാർ തേൻ തിന്നുതീർത്തുവെന്ന് വീരനായ ദധിമുഖൻ പറയുന്നു.",
        "0.16": "ദൗത്യത്തിൽ അവർ പരാജയപ്പെട്ടിരുന്നെങ്കിൽ ഇത്തരം അതിക്രമം സംഭവിക്കില്ലായിരുന്നു; അവർ തോട്ടത്തിൽ വീണതുകൊണ്ട് ദൗത്യം തീർച്ചയായും പൂർത്തിയായിരിക്കുന്നു.",
        "0.17": "അവരെ തടയാൻ വന്ന കാവൽക്കാർ മുട്ടുകൊണ്ട് അടിക്കപ്പെട്ടു; ഈ ശക്തനായ ദധിമുഖനെപ്പോലും ആരും ഗൗനിച്ചില്ല,",
        "0.18": "അവൻ എന്റെ തോട്ടത്തിന്റെ അധിപനാണെങ്കിലും, ഞാൻതന്നെ നിയമിച്ചവനാണ്. ദേവിയെ കണ്ടിരിക്കുന്നു, സംശയമില്ല; ഹനുമാനല്ലാതെ മറ്റാരുമല്ല അത് ചെയ്തത്.",
        "0.19": "ഈ ദൗത്യം നേടാൻ ഹനുമാനല്ലാതെ മറ്റാരും ഉപകരണമാകില്ല; വാനരശ്രേഷ്ഠനായ ഹനുമാനിൽ വിജയവും ജ്ഞാനവും വസിക്കുന്നു,",
        "0.20": "ഉറച്ച തീരുമാനവും വീര്യവും പാണ്ഡിത്യവും അവനിൽ ഉറച്ചിരിക്കുന്നു. ജാംബവാൻ നേതാവായിരിക്കുന്നിടത്തും, ശക്തനായ അംഗദനും,",
        "0.21": "ഹനുമാൻ നയിക്കുന്നിടത്തും മറ്റൊരു ഫലം ഉണ്ടാകാനിടയില്ല. മധുവനം അംഗദന്റെ നേതൃത്വത്തിലുള്ള വീരന്മാർ നശിപ്പിച്ചിരിക്കുന്നു എന്നു തോന്നുന്നു,",
        "0.22": "ദക്ഷിണദിക്ക് അന്വേഷിച്ച് മടങ്ങിയെത്തിയ വാനരപ്രമുഖന്മാർ; മടങ്ങിവന്ന്, ആ ലംഘിക്കാനാവാത്ത മധുവനം അവർ നശിപ്പിച്ചിരിക്കുന്നു.",
        "0.23": "വാനരന്മാർ മുഴുവൻ തോട്ടത്തെ കൊള്ളയടിച്ച് ആസ്വദിച്ചു; കാവൽക്കാർ നിലത്തിട്ട് മുട്ടുകൊണ്ട് അടിക്കപ്പെട്ടു.",
        "0.24": "ഇത് റിപ്പോർട്ട് ചെയ്യാനാണ് ഇവിടെ വന്നിരിക്കുന്നത്; മധുരമായി സംസാരിക്കുന്ന, പ്രസിദ്ധവീര്യമുള്ള ദധിമുഖൻ എന്ന ഈ വാനരൻ.",
        "0.25": "സുമിത്രാപുത്രാ, ബലിഷ്ഠബാഹോ, സീതയെ കണ്ടെത്തിയിരിക്കുന്നു; ഇത് എങ്ങനെയെന്ന് കാണൂ; വാനരന്മാരെല്ലാം വന്ന് തേൻ കുടിക്കുന്നു.",
        "0.26": "പുരുഷശ്രേഷ്ഠാ, രാജാവിന്റെ അനുമതിയാൽ സംരക്ഷിക്കപ്പെട്ട ആ ദിവ്യമായ തോട്ടം, വൈദേഹിയെ കാണാതെ പ്രസിദ്ധരായ വനവാസികൾ ഒരിക്കലും ലംഘിക്കില്ല.\"",
        "0.27": "സുഗ്രീവന്റെ അധരങ്ങളിൽനിന്ന് വീണ, ചെവിക്ക് ഇമ്പമുള്ള ആ വാക്കുകൾ കേട്ട്, ധർമ്മിഷ്ഠനായ ലക്ഷ്മണൻ രാഘവനോടൊപ്പം സന്തോഷിച്ചു.",
        "0.28": "രാമൻ വലിയ സന്തോഷം അനുഭവിച്ചു, തേജസ്വിയായ ലക്ഷ്മണനും. ദധിമുഖന്റെ വാക്കുകൾ കേട്ട് സന്തുഷ്ടനായ സുഗ്രീവനും,",
        "0.29": "തോട്ടത്തിന്റെ സൂക്ഷിപ്പുകാരനോട് വീണ്ടും പറഞ്ഞു: \"ദൗത്യം പൂർത്തിയാക്കിയവർ തോട്ടം ആസ്വദിച്ചതിൽ ഞാൻ സന്തുഷ്ടനാണ്.",
        "0.30": "ദൗത്യം നിർവ്വഹിച്ചവരുടെ പരുക്കൻ പ്രവൃത്തികൾ പൊറുക്കപ്പെടണം. വേഗം മധുവനത്തിലേക്ക് പോയി നീ തന്നെ അത് കാത്തുസൂക്ഷിക്കൂ; ഹനുമാൻ നയിക്കുന്ന വാനരന്മാരെയെല്ലാം ഉടൻ ഇവിടെ അയയ്ക്കൂ.",
        "0.31": "രണ്ടു രാഘവന്മാരോടൊപ്പം, സിംഹങ്ങളെപ്പോലെ അഭിമാനികളായി, ലക്ഷ്യം നേടിയ ഹനുമാൻ നയിക്കുന്ന ആ വാനരന്മാരോട് വേഗം ചോദിക്കാനും, സീതയെ കണ്ടെത്താനുള്ള അവരുടെ പ്രയത്നം കേൾക്കാനും ഞാൻ ആഗ്രഹിക്കുന്നു.\"",
        "0.32": "രണ്ടു രാജകുമാരന്മാരെയും, സന്തോഷംകൊണ്ട് വിടർന്ന കണ്ണുകളോടെ നോക്കി, ലക്ഷ്യം നേടിയതുപോലെ ആവേശഭരിതനായി, വിജയം അടുത്തെത്തി എന്ന് സ്വന്തം ആവേശഭരിതമായ അവയവങ്ങളാൽ അറിഞ്ഞ്, വാനരരാജാവ് അളവില്ലാതെ ആനന്ദിച്ചു.",
        "0.33": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപത്തിമൂന്നാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "ദധിമുഖൻ സുഗ്രീവന്റെ പാദങ്ങളിൽ വീണ് മധുവനം കൊള്ളയടിക്കപ്പെട്ട വിവരം അറിയിക്കുന്നു. വാനരന്മാർ സീതയെ കണ്ടെത്തിയിരിക്കണമെന്ന് ഊഹിച്ച്, സുഗ്രീവൻ സന്തോഷിക്കുകയും രാമനെയും ലക്ഷ്മണനെയും അറിയിക്കുകയും ചെയ്യുന്നു."
    },
    "sundarakanda-64": {
      "verses": {
        "0.0": "സുഗ്രീവൻ ഇങ്ങനെ പറഞ്ഞപ്പോൾ, സന്തോഷിച്ച ദധിമുഖൻ രാഘവനെയും ലക്ഷ്മണനെയും സുഗ്രീവനെയും വണങ്ങി.",
        "0.1": "സുഗ്രീവനെയും രണ്ടു മഹാവീരന്മാരായ രാഘവന്മാരെയും വണങ്ങിയശേഷം, ധീരരായ തന്റെ വാനരന്മാരോടൊപ്പം അവൻ ആകാശത്തേക്ക് കുതിച്ചുയർന്നു.",
        "0.2": "വന്നതുപോലെ വേഗത്തിൽ അവൻ മടങ്ങി; ആകാശത്തുനിന്ന് നിലത്തേക്ക് ഇറങ്ങി, ആ തോട്ടത്തിൽ പ്രവേശിച്ചു.",
        "0.3": "മധുവനത്തിൽ പ്രവേശിച്ചപ്പോൾ, ലഹരി തെളിഞ്ഞെങ്കിലും ഇപ്പോഴും ബഹളമയരായ വാനരപ്രമുഖന്മാർ തേൻ കുടിച്ചശേഷം മൂത്രമൊഴിക്കുന്നത് അവൻ കണ്ടു.",
        "0.4": "ആ വീരൻ കൈകൂപ്പി അവരുടെ അടുത്ത് ചെന്ന്, സന്തോഷത്തോടെ അംഗദനോട് ഈ മൃദുവാക്കുകൾ പറഞ്ഞു:",
        "0.5": "\"പ്രിയപ്പെട്ടവനേ, അജ്ഞാനത്താലും കോപത്താലും ഈ കാവൽക്കാർ നിങ്ങളെ എല്ലാവരെയും തടയാൻ ശ്രമിച്ചതിൽ കോപിക്കരുതേ.",
        "0.6": "നിങ്ങൾ ക്ഷീണിതരും ഏറെ ദൂരം വന്നവരുമാണ്; നിങ്ങളുടെ സ്വന്തം തേൻ ആസ്വദിച്ചുകൊള്ളൂ. നീ യുവരാജാവാണ്; ഈ തോട്ടത്തിന്റെ അധിപനും മഹാബലവാനുമാണ്.",
        "0.7": "വിഡ്ഢിത്തത്താൽ ഞാൻ നേരത്തേ കോപം കാണിച്ചു; ദയവായി അത് ക്ഷമിക്കണേ. മുൻപ് നിന്റെ പിതാവ് വാനരസൈന്യങ്ങളുടെ നാഥനായിരുന്നതുപോലെ,",
        "0.8": "നീയും, സുഗ്രീവനും, മറ്റാരുമല്ല, വാനരശ്രേഷ്ഠാ, നാഥന്മാരായിരിക്കുന്നു. നിർമ്മലനായവനേ, ഞാൻ പോയി നിന്റെ അമ്മാവനെ അറിയിച്ചു",
        "0.9": "ഈ വനവാസികളെല്ലാം ഇവിടെ എത്തിയിരിക്കുന്നു എന്ന്. ഈ വനവാസികളോടൊപ്പം നിങ്ങളുടെ വരവ് കേട്ടപ്പോൾ,",
        "0.10": "അവൻ സന്തോഷിച്ചു; തോട്ടം നശിപ്പിക്കപ്പെട്ടു എന്ന് കേട്ടിട്ടും അവന് കോപം ഒട്ടും ഉണ്ടായില്ല. നിന്റെ അമ്മാവനായ വാനരരാജാവ് സുഗ്രീവൻ സന്തോഷത്തോടെ,",
        "0.11": "രാജാവ് എന്നോട് പറഞ്ഞു: \"അവരെല്ലാം വേഗം ഇവിടേക്ക് അയക്കൂ.\" ദധിമുഖന്റെ ഈ മൃദുവാക്കുകൾ കേട്ട്, അംഗദൻ,",
        "0.12": "വാനരശ്രേഷ്ഠനും വാക്ചാതുര്യമുള്ളവനുമായ അംഗദൻ അവരോട് പറഞ്ഞു: \"വാനരസംഘങ്ങളുടെ നേതാക്കളേ, രാമൻ ഈ വാർത്ത കേട്ടിരിക്കുമെന്ന് ഞാൻ സംശയിക്കുന്നു,",
        "0.13": "ഇത് പറയുന്നവന്റെ സന്തോഷത്തിൽനിന്ന് ഞാൻ അറിയുന്നു. അതിനാൽ ദൗത്യം പൂർത്തിയായ ഇപ്പോൾ നമുക്ക് ഇവിടെ തങ്ങുന്നത് ശരിയല്ല, ശത്രുക്കളെ ചുട്ടെരിക്കുന്നവരേ.",
        "0.14": "വീരരായ വനവാസികളേ, നിങ്ങൾ ഹൃദയം നിറയെ തേൻ കുടിച്ചു; ഇനി വാനരനായ സുഗ്രീവൻ ഇരിക്കുന്നിടത്തേക്ക് പോകുകയല്ലാതെ മറ്റെന്തുണ്ട്?",
        "0.15": "നിങ്ങൾ വാനരപ്രമുഖന്മാർ എല്ലാവരും ചേർന്ന് എന്നോട് പറയുന്നതെന്തും ഞാൻ ചെയ്യും; ചെയ്യേണ്ട കാര്യത്തിൽ ഞാൻ നിങ്ങളെ ആശ്രയിച്ചിരിക്കുന്നു.",
        "0.16": "ഞാൻ യുവരാജാവാണെങ്കിലും നിങ്ങളോട് കല്പിക്കാൻ എനിക്ക് അവകാശമില്ല; ദൗത്യം നിറവേറ്റിയ നിങ്ങളെ ബലമായി മറികടക്കുന്നത് ഉചിതമല്ല.\"",
        "0.17": "അംഗദന്റെ ഈ ഉത്തമവാക്കുകൾ കേട്ട്, വനവാസികൾ ഹൃദയത്തിൽ സന്തോഷിച്ച് മറുപടി പറഞ്ഞു:",
        "0.18": "\"രാജാവേ, വാനരശ്രേഷ്ഠാ, ഒരു നാഥനായിരിക്കുന്നവൻ ഇങ്ങനെ സംസാരിക്കുമോ? അധികാരത്തിന്റെ അഹങ്കാരത്താൽ ലഹരിപിടിച്ച എല്ലാവരും 'ഞാൻതന്നെ എല്ലാം' എന്ന് ചിന്തിക്കുന്നു.",
        "0.19": "ഈ വാക്കുകൾ നിനക്ക് മാത്രം യോജിച്ചതാണ്; നിന്റെ വിനയം ഭാവിയിലെ നന്മയ്ക്ക് നീ യോഗ്യനാണെന്ന് കാണിക്കുന്നു.",
        "0.20": "വാനരവീരന്മാരുടെ എന്നന്നേക്കുമുള്ള നാഥനായ സുഗ്രീവൻ ഇരിക്കുന്നിടത്തേക്ക് പോകാൻ ഞങ്ങളും എല്ലാവരും ഒരുക്കവും ആവേശവുമുള്ളവരാണ്.",
        "0.21": "വാനരശ്രേഷ്ഠാ, നിന്റെ വാക്കില്ലാതെ വാനരന്മാർക്ക് എവിടെയും ഒരു ചുവടുപോലും വെക്കാനാവില്ല; ഇത് ഞങ്ങൾ സത്യമായി പറയുന്നു.\"",
        "0.22": "ഇത് പറഞ്ഞപ്പോൾ, അംഗദൻ \"നല്ലത്, നമുക്ക് പോകാം\" എന്ന് മറുപടി പറഞ്ഞു; അങ്ങനെ പറഞ്ഞ് ആ ശക്തരായവർ ആകാശത്തേക്ക് കുതിച്ചുയർന്നു.",
        "0.23": "അവൻ പറന്നുയർന്നപ്പോൾ, മറ്റെല്ലാ സംഘനേതാക്കളും അവന്റെ പിന്നാലെ പറന്നു; കവണയിൽനിന്ന് എറിഞ്ഞ കല്ലുകൾപോലെ, ആകാശത്ത് ഒരിടവും ശേഷിപ്പിക്കാതെ.",
        "0.24": "അംഗദനെയും വാനരനായ ഹനുമാനെയും മുന്നിൽ നിർത്തി, ആ വേഗമുള്ള വാനരന്മാർ പെട്ടെന്ന് ആകാശത്തേക്ക് കുതിച്ചുചാടി,",
        "0.25": "കാറ്റാൽ ഓടിക്കപ്പെടുന്ന മേഘങ്ങൾപോലെ ഉച്ചത്തിൽ ഗർജ്ജിച്ചുകൊണ്ട്. അംഗദൻ അടുത്തെത്തിയപ്പോൾ, വാനരരാജാവ് സുഗ്രീവൻ,",
        "0.26": "ദുഃഖത്താൽ എരിയുന്ന താമരക്കണ്ണുള്ള രാമനോട് പറഞ്ഞു: \"ധൈര്യമായിരിക്കൂ, നിനക്ക് നന്മ വരട്ടെ; ദേവി കണ്ടെത്തിയിരിക്കുന്നു, സംശയമില്ല.",
        "0.27": "നിശ്ചയിച്ച സമയം കഴിഞ്ഞാണ് അവർ ഇവിടേക്ക് മടങ്ങിവരുന്നത്; അല്ലെങ്കിൽ അവർക്ക് മടങ്ങിവരാൻ കഴിയുമായിരുന്നില്ല; അംഗദന്റെ സന്തോഷത്തിൽനിന്ന് ഞാൻ ഇത് അറിയുന്നു, സുന്ദരാ.",
        "0.28": "ദൗത്യം പരാജയപ്പെട്ടിരുന്നെങ്കിൽ, ബലിഷ്ഠബാഹുവായ യുവരാജാവ് അംഗദൻ, കുതിക്കുന്നവരിൽ ശ്രേഷ്ഠൻ, എന്റെ അടുത്തേക്ക് വരില്ലായിരുന്നു;",
        "0.29": "പരാജയപ്പെട്ടവർ ഇങ്ങനെ മടങ്ങിവന്നാലും, അവൻ താഴ്ന്ന മുഖത്തോടെ, ആശയക്കുഴപ്പവും വിഷമവുമുള്ള മനസ്സോടെ വരുമായിരുന്നു.",
        "0.30": "പൂർവ്വികരാൽ സംരക്ഷിക്കപ്പെട്ടതും പൈതൃകമായതുമായ എന്റെ മധുവനം, ജനകപുത്രിയെ കാണാതെ അവർ നശിപ്പിക്കുമായിരുന്നില്ല.",
        "0.31": "സത്യവ്രതനായ രാമാ, കൗസല്യ മകനാൽ അനുഗൃഹീതയാണ്; ധൈര്യമായിരിക്കൂ. ദേവി കണ്ടെത്തിയിരിക്കുന്നു, സംശയമില്ല; ഹനുമാനല്ലാതെ മറ്റാരുമല്ല അത് കണ്ടത്.",
        "0.32": "ഈ ദൗത്യം നേടാൻ ഹനുമാനല്ലാതെ മറ്റാരും ഉപകരണമാകില്ല; ജ്ഞാനികളിൽ ശ്രേഷ്ഠനായ ഹനുമാനിൽ വിജയവും ജ്ഞാനവും ഉണ്ട്,",
        "0.33": "ഉറച്ച തീരുമാനവും ധൈര്യവും പാണ്ഡിത്യവും ഉറച്ചിരിക്കുന്നു. ജാംബവാൻ നേതാവായിരിക്കുന്നിടത്തും, വാനരരാജാവായ അംഗദനും,",
        "0.34": "ഹനുമാൻ നയിക്കുന്നിടത്തും, മറ്റൊരു ഫലം ഉണ്ടാകാനിടയില്ല. അതിരില്ലാത്ത വീര്യമുള്ളവനേ, ഇപ്പോൾ ആശങ്കയാൽ വിഷമിക്കരുതേ.",
        "0.35": "വനവാസികൾ ഇത്ര അഭിമാനത്തോടെയും ആഹ്ലാദത്തോടെയും ഒന്നിച്ചുചേർന്നിരിക്കുമ്പോൾ, അവർ ദൗത്യത്തിൽ പരാജയപ്പെട്ടിരുന്നെങ്കിൽ ഈ പെരുമാറ്റം അവർക്ക് ഉണ്ടാകുമായിരുന്നില്ല.",
        "0.36": "\"തോട്ടം തകർക്കപ്പെട്ടതും തേൻ തിന്നതുമായ കാര്യത്തിൽനിന്ന് ഞാൻ അത് അറിയുന്നു.\" അപ്പോൾ അടുത്ത് ആകാശത്ത് സന്തോഷകരമായ ആരവം അവൻ കേട്ടു,",
        "0.37": "ഹനുമാന്റെ വീരകൃത്യത്തിൽ അഭിമാനിച്ച വനവാസികളുടെ, കിഷ്കിന്ധയിലേക്ക് വരുമ്പോൾ ഗർജ്ജിക്കുന്ന ശബ്ദം, വിജയം പ്രഖ്യാപിക്കുന്നതുപോലെ.",
        "0.38": "വാനരന്മാരുടെ ആ ആർപ്പുവിളി കേട്ട്, വാനരശ്രേഷ്ഠൻ, വാൽ നീട്ടി വളച്ചുപിടിച്ച്, ഹൃദയത്തിൽ സന്തോഷിച്ചു.",
        "0.39": "രാമനെ കാണാൻ ആഗ്രഹിച്ചുകൊണ്ട്, അംഗദനും വാനരനായ ഹനുമാനും മുന്നിൽ നിൽക്കെ വാനരന്മാർ എത്തി.",
        "0.40": "ആഹ്ലാദത്തോടെയും സന്തോഷം നിറഞ്ഞവരായി, അംഗദന്റെ നേതൃത്വത്തിലുള്ള ആ വീരന്മാർ വാനരരാജാവിനും രാഘവനുമടുത്ത് ഇറങ്ങി.",
        "0.41": "ശക്തരായ ബാഹുക്കളുള്ള ഹനുമാൻ തല കുനിച്ച്, ദേവി പതിവ്രതയും ക്ഷേമമുള്ളവളുമാണെന്ന് രാഘവനോട് പറഞ്ഞു.",
        "0.42": "ഹനുമാന്റെ ചുണ്ടുകളിൽനിന്ന് \"ദേവിയെ കണ്ടിരിക്കുന്നു\" എന്ന അമൃതുപോലുള്ള വാക്കുകൾ കേട്ട്, ലക്ഷ്മണനോടൊപ്പം രാമൻ സന്തോഷത്താൽ നിറഞ്ഞു.",
        "0.43": "സന്തുഷ്ടനായ ലക്ഷ്മണൻ, വായുപുത്രനെക്കുറിച്ച് ഉറപ്പുണ്ടായിരുന്ന സന്തുഷ്ടനായ സുഗ്രീവനെ വലിയ ആദരവോടെ നോക്കി.",
        "0.44": "ശത്രുവീരന്മാരെ വധിക്കുന്ന രാഘവൻ, പരമമായ സന്തോഷം നിറഞ്ഞവനായി, ഹനുമാനെ വലിയ ആദരവോടെ നോക്കി.",
        "0.45": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപത്തിനാലാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "സുഗ്രീവൻ മടക്കി അയച്ച ദധിമുഖൻ അംഗദനോട് ക്ഷമ ചോദിക്കുകയും വാനരന്മാരോട് വേഗം വരാൻ ആവശ്യപ്പെടുകയും ചെയ്യുന്നു. അവർ കിഷ്കിന്ധയിലേക്ക് പറക്കുന്നു; സീത സുരക്ഷിതയും വിശ്വസ്തയുമായി കണ്ടെത്തിയെന്ന് ഹനുമാൻ രാമനെ അറിയിക്കുന്നു."
    },
    "sundarakanda-65": {
      "verses": {
        "0.0": "പിന്നെ, അത്ഭുതകരമായ വനങ്ങളുള്ള പ്രസ്രവണപർവ്വതത്തിലേക്ക് പോയി, അവർ രാമനെയും മഹാബലവാനായ ലക്ഷ്മണനെയും വണങ്ങി;",
        "0.1": "യുവരാജാവിനെ മുന്നിൽ നിർത്തി സുഗ്രീവനെ വന്ദിച്ചു; പിന്നെ അവർ സീതയുടെ വാർത്ത പറഞ്ഞുതുടങ്ങി:",
        "0.2": "രാവണന്റെ അന്തഃപുരത്തിലെ തടവ്, രാക്ഷസിമാരുടെ ഭീഷണികൾ, രാമനോടുള്ള അവളുടെ ആഴമായ സ്നേഹം, അവൾ എടുത്ത പ്രതിജ്ഞ.",
        "0.3": "വാനരന്മാർ ഇതെല്ലാം രാമന്റെ സാന്നിധ്യത്തിൽ വിവരിച്ചപ്പോൾ, വൈദേഹി ക്ഷേമത്തോടെയുണ്ടെന്ന് കേട്ട രാമൻ മറുപടിയായി പറഞ്ഞു:",
        "0.4": "\"ദേവി സീത ഇപ്പോൾ എവിടെയാണ്? എന്നോട് അവൾക്കുള്ള മനോഭാവം എന്താണ്? വാനരന്മാരേ, വൈദേഹിയെക്കുറിച്ച് ഇതെല്ലാം എന്നോട് പറയൂ.\"",
        "0.5": "രാമന്റെ വാക്കുകൾ കേട്ട്, സീതയുടെ കഥ നന്നായി അറിയുന്ന ഹനുമാനോട് സംസാരിക്കാൻ രാമന്റെ സാന്നിധ്യത്തിലുണ്ടായിരുന്ന വാനരന്മാർ ആവശ്യപ്പെട്ടു.",
        "0.6": "അവരുടെ വാക്കുകൾ കേട്ട്, വായുപുത്രനായ ഹനുമാൻ ദേവി സീത ഇരിക്കുന്ന ദിശയിലേക്ക് തല കുനിച്ചു,",
        "0.7": "സീതയെ താൻ കണ്ട വിവരം സംസാരചതുരനായി പറഞ്ഞു. ആ ദിവ്യമായ സ്വർണ്ണ രത്നം, സ്വന്തം പ്രകാശത്താൽ ജ്വലിച്ചുകൊണ്ട്,",
        "0.8": "ഹനുമാൻ രാമന് നൽകി, പിന്നെ കൈകൂപ്പി പറഞ്ഞു: \"നൂറ് യോജന വീതിയുള്ള സമുദ്രം കടന്ന്,",
        "0.9": "ജാനകിയായ സീതയെ, അവളെ കാണാനുള്ള ആഗ്രഹത്തോടെ ഞാൻ അന്വേഷിച്ചുപോയി. ദുഷ്ടനായ രാവണന്റേതായി ലങ്ക എന്ന് പേരുള്ള ഒരു നഗരമുണ്ട്,",
        "0.10": "ദക്ഷിണ സമുദ്രത്തിന്റെ തെക്കേ തീരത്ത്. അവിടെ ഞാൻ രാവണന്റെ അന്തഃപുരത്തിൽ പുണ്യവതിയായ സീതയെ കണ്ടു.",
        "0.11": "മനോഹരിയായ ആ സ്ത്രീ, രാമാ, നിന്നിൽ എല്ലാ പ്രതീക്ഷയും അർപ്പിച്ച് ജീവിക്കുന്നു. രാക്ഷസിമാർക്കിടയിൽ, ആവർത്തിച്ച് ഭീഷണിപ്പെടുത്തപ്പെടുന്നവളായി ഞാൻ അവളെ കണ്ടു;",
        "0.12": "വിനോദോദ്യാനത്തിൽ ഭയങ്കരരായ രാക്ഷസിമാരാൽ കാക്കപ്പെട്ട്. നിന്നോടൊപ്പം സന്തോഷത്തിന് അർഹയായ ദേവി, വീരാ, ദുഃഖം സഹിക്കുന്നു.\"",
        "0.13": "രാവണന്റെ അന്തഃപുരത്തിൽ തടവിലാക്കപ്പെട്ട്, രാക്ഷസിമാരാൽ കർശനമായി കാക്കപ്പെട്ട്, ഒറ്റ ജടയണിഞ്ഞ്, ദയനീയയായി, അവൾ നിന്നെക്കുറിച്ചുള്ള ചിന്തയിൽ മുഴുകിയിരിക്കുന്നു;",
        "0.14": "അവൾ നിലത്ത് ഉറങ്ങുന്നു, മഞ്ഞുകാലം വരുമ്പോൾ വാടിയ താമരച്ചെടിപോലെ വിളറി; രാവണനിൽനിന്ന് മുഖം തിരിച്ച്, മരിക്കാൻ ഉറച്ചിരിക്കുന്നു.",
        "0.15": "എങ്ങനെയോ, കാകുത്സ്ഥാ, ഇക്ഷ്വാകുവംശത്തിന്റെ മഹിമ മൃദുവായി ഉരുവിട്ടുകൊണ്ട് ഞാൻ, നിന്നിൽ മനസ്സുറപ്പിച്ച ദേവിയെ കണ്ടെത്തി, നിർമ്മലനായവനേ.",
        "0.16": "പിന്നെ, മനുഷ്യരിൽ വ്യാഘ്രമായവനേ, ഞാൻ ക്രമേണ അവളുടെ വിശ്വാസം നേടി; പിന്നെ ദേവിയോട് സംസാരിച്ച് എല്ലാം അവൾക്ക് വ്യക്തമാക്കി.",
        "0.17": "രാമന്റെയും സുഗ്രീവന്റെയും സൗഹൃദം കേട്ട് അവൾ സന്തോഷത്താൽ നിറഞ്ഞു. അവളുടെ നടപ്പ് അച്ചടക്കമുള്ളത്; അവളുടെ ഭക്തി എന്നും നിന്നിൽ ഉറച്ചിരിക്കുന്നു.",
        "0.18": "അങ്ങനെ, ഐശ്വര്യവാനേ, നിന്നോടുള്ള ഭക്തിയാൽ കഠിനതപസ്സിലേർപ്പെട്ട ജനകപുത്രിയെ, പുരുഷശ്രേഷ്ഠനേ, ഞാൻ കണ്ടു.",
        "0.19": "അവൾ എനിക്ക് ഒരു അടയാളം തന്നു, ജ്ഞാനിയായ രാഘവാ: ചിത്രകൂടത്തിൽ വെച്ച് കാകനെക്കുറിച്ച് നിന്റെ സാന്നിധ്യത്തിൽ സംഭവിച്ചത്.",
        "0.20": "\"വായുപുത്രാ, നീ കണ്ടതെല്ലാം രാമനോട് വീണ്ടും പൂർണ്ണമായി പറയൂ,\" ജാനകി എന്നോട് പറഞ്ഞു.",
        "0.21": "\"ഇത് സൂക്ഷ്മമായി സൂക്ഷിച്ച്, അദ്ദേഹത്തിന് നൽകണം.\" അങ്ങനെ അവൾ പറഞ്ഞു; ഇപ്പോൾ സുഗ്രീവൻ കേൾക്കെ ഞാൻ അവളുടെ വാക്കുകൾ അറിയിക്കുന്നു:",
        "0.22": "\"ഈ ശ്രേഷ്ഠമായ ചൂഡാമണി നിനക്കുവേണ്ടി ഞാൻ സൂക്ഷിച്ചുവെച്ചിരുന്നു; ചുവന്ന മനഃശിലയുടെ തിലകം ഓർക്കണം,\" അവൾ പറഞ്ഞു.",
        "0.23": "\"ഈ ശ്രേഷ്ഠമായ ജലജരത്നം ഞാൻ നിനക്ക് തിരിച്ചയക്കുന്നു; നിർമ്മലനായവനേ, എന്റെ ദുഃഖത്തിൽ അത് കാണുമ്പോൾ നിന്നെ കണ്ടതുപോലെ ഞാൻ സന്തോഷിച്ചിരുന്നു.",
        "0.24": "ഒരു മാസത്തേക്ക് ഞാൻ ജീവൻ നിലനിർത്തും, ദശരഥപുത്രാ; ഒരു മാസം കഴിഞ്ഞ് ഞാൻ ജീവിക്കില്ല; രാക്ഷസരുടെ അധികാരത്തിൽ വീണുപോയി.\"",
        "0.25": "ഇങ്ങനെ സീത ദേഹം ക്ഷീണിച്ച്, ധർമ്മപഥത്തിൽ നടന്ന്, രാവണന്റെ അന്തഃപുരത്തിൽ തടവിലായി, മാനിന്റേതുപോലെ വിടർന്ന കണ്ണുകളോടെ എന്നോട് പറഞ്ഞു.",
        "0.26": "രാഘവാ, സംഭവിച്ചതുപോലെ എനിക്ക് പറയാനുള്ളതെല്ലാം ഇത്രയേയുള്ളൂ. എല്ലാ വഴികളിലൂടെയും സമുദ്രജലം കടക്കാനുള്ള ഏർപ്പാട് ചെയ്യപ്പെടട്ടെ.\"",
        "0.27": "രണ്ടു രാജകുമാരന്മാരും ധൈര്യം വീണ്ടെടുക്കുന്നത് കണ്ട്, ആ അടയാളം രാഘവന് കൈമാറിയശേഷം, വായുപുത്രൻ ദേവി പറഞ്ഞതെല്ലാം ക്രമത്തിൽ പൂർണ്ണമായി വിവരിച്ചു.",
        "0.28": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപത്തഞ്ചാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "പ്രസ്രവണപർവ്വതത്തിൽ വാനരന്മാർ രാമനെ വണങ്ങുന്നു; സീത എങ്ങനെയാണ് തടവിലാക്കപ്പെട്ടിരിക്കുന്നതെന്നും അവൾ എന്തെല്ലാം സഹിക്കുന്നുവെന്നും ഹനുമാൻ വിവരിക്കുന്നു. അവൾ അയച്ച ചൂഡാമണി അദ്ദേഹം രാമന് കൈമാറുന്നു."
    },
    "sundarakanda-66": {
      "verses": {
        "0.0": "ഹനുമാൻ ഇത് പറഞ്ഞപ്പോൾ, ദശരഥപുത്രനായ രാമൻ ആ രത്നം നെഞ്ചോട് ചേർത്ത്, ലക്ഷ്മണനോടൊപ്പം കരഞ്ഞു.",
        "0.1": "ഏറ്റവും മികച്ച ആ രത്നം നോക്കി, ദുഃഖത്താൽ ക്ഷീണിച്ച്, കണ്ണുനീർ നിറഞ്ഞ കണ്ണുകളോടെ രാഘവൻ സുഗ്രീവനോട് ഇങ്ങനെ പറഞ്ഞു:",
        "0.2": "\"കിടാവിനോടുള്ള സ്നേഹത്താൽ സ്നേഹമുള്ള പശു ചുരത്തുന്ന പാൽപോലെ, ഈ ശ്രേഷ്ഠമായ രത്നം കാണുമ്പോൾ എന്റെ ഹൃദയവും ഉരുകുന്നു.",
        "0.3": "ഈ വിലപിടിപ്പുള്ള രത്നം എന്റെ ശ്വശുരൻ വൈദേഹിക്ക് നൽകിയതാണ്; വിവാഹവേളയിൽ അവളുടെ തലയിൽ ഉറപ്പിച്ചപ്പോൾ അത് കൂടുതൽ തിളങ്ങി.",
        "0.4": "ശ്രേഷ്ഠന്മാർ ആദരിച്ച ഈ ജലജരത്നം, യജ്ഞത്തിൽ വളരെ സന്തുഷ്ടനായ ജ്ഞാനിയായ ഇന്ദ്രൻ നൽകിയതാണ്.",
        "0.5": "ഈ ഏറ്റവും മികച്ച രത്നം കാണുമ്പോൾ, സുഹൃത്തേ, ഇന്ന് എന്റെ പിതാവിനെയും വിദേഹരാജാവിനെയും കണ്ടതുപോലെയുണ്ട്.",
        "0.6": "ഈ രത്നം എന്റെ പ്രിയതമയുടെ തലയിൽ പ്രകാശിച്ചു; ഇന്ന് അത് കാണുമ്പോൾ അവളെ വീണ്ടും കണ്ടെത്തിയതുപോലെ തോന്നുന്നു.",
        "0.7": "സീത, വൈദേഹി, എന്ത് പറഞ്ഞു? സുഹൃത്തേ, മരിച്ചുകൊണ്ടിരിക്കുന്ന ഒരാളെ വെള്ളം തളിച്ച് ഉണർത്തുന്നതുപോലെ, അവളുടെ വാക്കുകളുടെ ജലം എന്നിൽ തളിച്ചുകൊണ്ട് വീണ്ടും വീണ്ടും പറയൂ.",
        "0.8": "സുമിത്രാപുത്രാ, വൈദേഹി കൂടെ വരാതെ, ഈ ജലജരത്നം കാണുന്നതിനെക്കാൾ വേദനാജനകമായി മറ്റെന്തുണ്ട്?",
        "0.9": "ഒരു മാസം പിടിച്ചുനിന്നാൽ വൈദേഹി ദീർഘകാലം ജീവിക്കും; കറുത്ത കണ്ണുള്ളവളില്ലാതെ, വീരാ, എനിക്ക് ഒരു നിമിഷംപോലും ജീവിക്കാനാവില്ല.",
        "0.10": "എന്റെ പ്രിയതമയെ കണ്ടിടത്തേക്ക് എന്നെയും കൊണ്ടുപോകൂ; അവളെക്കുറിച്ചുള്ള വാർത്ത കിട്ടിയ ശേഷം, ഒരു നിമിഷംപോലും ഇവിടെ നിൽക്കാൻ എനിക്ക് കഴിയില്ല.",
        "0.11": "മനോഹരമായ തുടകളുള്ള, ഏറ്റവും ലജ്ജാശീലയായ, പുണ്യവതിയായ എന്റെ പ്രിയ ആ ഭീകരരായ, ഭയപ്പെടുത്തുന്ന രാക്ഷസരുടെ ഇടയിൽ ഇപ്പോൾ എങ്ങനെ ജീവിക്കുന്നു?",
        "0.12": "ഇരുട്ടിൽനിന്ന് മോചിതനായ ശരത്കാലചന്ദ്രനെപ്പോലെ, മേഘങ്ങൾ വീണ്ടും മറച്ച ആ മുഖം ഇപ്പോൾ തിളങ്ങുന്നില്ല എന്ന് തീർച്ച.",
        "0.13": "ഹനുമാനേ, സീത എന്ത് പറഞ്ഞു? സത്യമായി പറയൂ. മരുന്നുകൊണ്ട് രോഗി ജീവിക്കുന്നതുപോലെ, ഇതുകൊണ്ടുമാത്രമേ ഞാൻ ജീവിക്കൂ.",
        "0.14": "എന്നിൽനിന്ന് വേർപിരിഞ്ഞ, സ്നേഹത്തോടെ സംസാരിക്കുന്ന, മധുരമായി സംസാരിക്കുന്ന, സുന്ദരിയായ എന്റെ പ്രിയ എന്ത് പറഞ്ഞു? ഹനുമാനേ, പറയൂ: ദുഃഖത്തിൽനിന്ന് കൂടുതൽ ദുഃഖത്തിലേക്ക് വീണുകൊണ്ട് ജാനകി എങ്ങനെ ജീവിക്കുന്നു?\"",
        "0.15": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപത്തിയാറാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "ചൂഡാമണി നെഞ്ചോട് ചേർത്ത് രാമൻ ലക്ഷ്മണനോടൊപ്പം കരയുന്നു; സീതയെയും ജനകമഹാരാജാവിനെയും ഓർക്കുന്നു. സീത പറഞ്ഞ ഓരോ വാക്കും ആവർത്തിച്ച് പറയാൻ അവൻ ഹനുമാനോട് ആവശ്യപ്പെടുന്നു."
    },
    "sundarakanda-67": {
      "verses": {
        "0.0": "മഹാത്മാവായ രാഘവൻ ഇങ്ങനെ ചോദിച്ചപ്പോൾ, സീത പറഞ്ഞതെല്ലാം ഹനുമാൻ രാഘവനെ അറിയിച്ചു.",
        "0.1": "\"പുരുഷശ്രേഷ്ഠാ, ജാനകീദേവി എനിക്ക് ഈ അടയാളം പറഞ്ഞുതന്നു; ചിത്രകൂടത്തിൽ മുൻപ് നടന്ന സംഭവം, അത് നടന്നതുപോലെതന്നെ:",
        "0.2": "നിങ്ങളോടൊപ്പം സുഖമായി ഉറങ്ങിക്കൊണ്ടിരുന്ന ജാനകി ആദ്യം ഉണർന്നു; പെട്ടെന്ന് ഒരു കാക്ക താഴേക്ക് പാഞ്ഞിറങ്ങി അവളുടെ മാറ് കൊത്തിക്കീറി.",
        "0.3": "പിന്നീട് നിങ്ങൾ ദേവിയുടെ മടിയിൽ മാറിമാറി ഉറങ്ങി, ഭരതന്റെ ജ്യേഷ്ഠാ; ആ പക്ഷി, പറയുന്നതുപോലെ, ദേവിയെ വീണ്ടും ശല്യപ്പെടുത്തി.",
        "0.4": "വീണ്ടും തിരിച്ചുവന്ന് അത് അവളെ മോശമായി മുറിവേൽപ്പിച്ചു; പിന്നെ നിങ്ങൾ ഉണർന്നു, അവളുടെ രക്തത്താൽ നനഞ്ഞവനായി.",
        "0.5": "അങ്ങനെ, ആ കാക്കയാൽ നിരന്തരം ശല്യപ്പെട്ട ദേവി, ശത്രുക്കളെ ചുട്ടെരിക്കുന്നവനേ, നിന്റെ സമാധാനപരമായ ഉറക്കത്തിൽനിന്ന് നിന്നെ ഉണർത്തി.",
        "0.6": "മാറ് കീറപ്പെട്ടത് കണ്ട്, ശക്തബാഹുവേ, നീ വിഷമുള്ള സർപ്പംപോലെ കോപിച്ച് പറഞ്ഞു:",
        "0.7": "\"ഭീരുവേ, നഖാഗ്രങ്ങളാൽ ആരാണ് നിന്റെ മാറ് കീറിയത്? കോപിച്ച അഞ്ചുതലയുള്ള സർപ്പത്തോടൊപ്പം കളിക്കുന്നത് ആരാണ്?\"",
        "0.8": "ചുറ്റും നോക്കിയപ്പോൾ, നിനക്ക് പെട്ടെന്ന് രക്തം പുരണ്ട മൂർച്ചയുള്ള നഖങ്ങളുമായി, അവൾക്ക് അഭിമുഖമായി ഇരിക്കുന്ന കാക്കയെ കാണാൻ കഴിഞ്ഞു.",
        "0.9": "പക്ഷികളിൽ ശ്രേഷ്ഠനായ ആ കാക്ക, പറയുന്നതുപോലെ ഇന്ദ്രപുത്രനായിരുന്നു; ഭൂമിയിൽ വേഗത്തിൽ സഞ്ചരിക്കുന്നവനും വേഗതയിൽ വായുവിന് തുല്യനുമായിരുന്നു.",
        "0.10": "പിന്നെ, ശക്തബാഹുവേ, ജ്ഞാനികളിൽ ശ്രേഷ്ഠനേ, കോപത്താൽ കണ്ണുകൾ ഉരുട്ടി, നീ ആ കാക്കയ്ക്ക് കഠിനശിക്ഷ നിശ്ചയിച്ചു.",
        "0.11": "നിന്റെ പുൽമെത്തയിൽനിന്ന് ഒരു ദർഭപ്പുല്ലിന്റെ തണ്ട് എടുത്ത്, അതിൽ ബ്രഹ്മാസ്ത്രം ആവാഹിച്ചു; അത് പ്രളയാഗ്നിപോലെ ജ്വലിച്ചു, പക്ഷിക്ക് നേരെ തിരിഞ്ഞു.",
        "0.12": "ആ ജ്വലിക്കുന്ന പുല്ല് നീ കാക്കയ്ക്ക് നേരെ എറിഞ്ഞു; ജ്വലിക്കുന്ന പുല്ല് കാക്കയെ പിന്തുടർന്നു.",
        "0.13": "ഭയന്നുപോയ ദേവന്മാരെല്ലാം കൈവിട്ട കാക്ക മൂന്നു ലോകവും ചുറ്റി, ഒരു സംരക്ഷകനെയും കണ്ടെത്തിയില്ല.",
        "0.14": "ശത്രുക്കളെ അടക്കുന്നവനേ, അത് വീണ്ടും നിന്റെ അടുത്തേക്ക് തന്നെ വന്നു; സർവ്വർക്കും അഭയമായ നീ, അത് അഭയം തേടി നിലത്ത് വീണുകിടക്കുന്നത് കണ്ടു,",
        "0.15": "മരണം അർഹിച്ചിരുന്നെങ്കിലും, കാരുണ്യത്താൽ അതിനെ സംരക്ഷിച്ചു, കാകുത്സ്ഥാ. എന്നാൽ ആ അസ്ത്രം നിഷ്ഫലമാക്കാൻ കഴിയാത്തതിനാൽ, രാഘവാ,",
        "0.16": "ആ കാക്കയുടെ വലത്തെ കണ്ണ് നീ നശിപ്പിച്ചു. പിന്നെ, രാമാ, നിന്നെയും ദശരഥമഹാരാജാവിനെയും വണങ്ങിയശേഷം,",
        "0.17": "കാക്ക മോചിതമായി സ്വന്തം വീട്ടിലേക്ക് തിരിച്ചുപോയി. അസ്ത്രവിദ്യയിൽ ശ്രേഷ്ഠനും അത്ര ശക്തനും പുണ്യവാനുമായ നീ,",
        "0.18": "രാഘവാ, നിന്റെ അസ്ത്രങ്ങൾ എന്തുകൊണ്ട് രാക്ഷസർക്കെതിരെ ഉപയോഗിക്കുന്നില്ല? ദാനവന്മാർക്കും ഗന്ധർവ്വന്മാർക്കും അസുരന്മാർക്കും മരുത്തുക്കളുടെ സൈന്യത്തിനും,",
        "0.19": "യുദ്ധത്തിൽ നിന്റെ മുന്നിൽ നിൽക്കാനാവില്ല, രാമാ. ഇത്ര ശക്തനായ നിനക്ക് എന്നോട് എന്തെങ്കിലും താല്പര്യമുണ്ടെങ്കിൽ,",
        "0.20": "മൂർച്ചയുള്ള അമ്പുകളാൽ യുദ്ധത്തിൽ രാവണനെ വേഗം വധിക്കട്ടെ. അല്ലെങ്കിൽ, ശത്രുക്കളെ ചുട്ടെരിക്കുന്ന ലക്ഷ്മണൻ, സഹോദരന്റെ കല്പനപ്രകാരം—",
        "0.21": "മനുഷ്യരിൽ ശ്രേഷ്ഠനായ രാഘവൻ എന്തുകൊണ്ട് എന്നെ സംരക്ഷിക്കുന്നില്ല? കാറ്റിനും അഗ്നിക്കും തുല്യമായ തേജസ്സുള്ള ആ രണ്ടു മനുഷ്യവ്യാഘ്രങ്ങൾ കഴിവുള്ളവരാണ്;",
        "0.22": "ദേവന്മാർക്കുപോലും അജയ്യരാണ്; എന്തുകൊണ്ട് അവർ എന്നെ അവഗണിക്കുന്നു? തീർച്ചയായും എനിക്ക് തന്നെ എന്തോ വലിയ പാപമുണ്ടായിരിക്കണം,",
        "0.23": "കഴിവുള്ള ആ രണ്ടു ശത്രുക്കളെ ചുട്ടെരിക്കുന്നവർ ഒന്നിച്ചിട്ടും എന്നെ രക്ഷിക്കുന്നില്ല.' വൈദേഹിയുടെ, ഇത്ര ഉദാത്തമായി പറയപ്പെട്ട ദയനീയ വാക്കുകൾ കേട്ട്,",
        "0.24": "ഞാൻ ആ ശ്രേഷ്ഠയായ സ്ത്രീയോട് ഇങ്ങനെ പറഞ്ഞു: 'ദേവീ, നിനക്കുവേണ്ടിയുള്ള ദുഃഖത്താൽ രാമൻ എല്ലാത്തിൽനിന്നും വിമുഖനായിരിക്കുന്നു; ഞാൻ ഇത് സത്യത്തിൽ നിന്നോട് ശപഥം ചെയ്യുന്നു.",
        "0.25": "ദുഃഖത്താൽ നിറഞ്ഞ രാമനോടൊപ്പം ലക്ഷ്മണനും കഷ്ടപ്പെടുന്നു. ഒരുവിധം നീ കണ്ടെത്തപ്പെട്ടിരിക്കുന്നു; ഇത് ദുഃഖിക്കാനുള്ള സമയമല്ല.",
        "0.26": "ഈ നിമിഷംതന്നെ, സ്ത്രീയേ, നിന്റെ ദുഃഖങ്ങളുടെ അന്ത്യം നീ കാണും. ശത്രുക്കളെ ചുട്ടെരിക്കുന്ന ആ രണ്ടു മനുഷ്യവ്യാഘ്രങ്ങളായ രാജകുമാരന്മാർ,",
        "0.27": "നിന്നെ കാണാനുള്ള ആവേശത്താൽ ലങ്കയെ ചാമ്പലാക്കും; യുദ്ധത്തിൽ ഉഗ്രനായ രാവണനെ ബന്ധുക്കളോടൊപ്പം വധിച്ച ശേഷം,",
        "0.28": "രാഘവൻ നിന്നെ, സുന്ദരീ, സ്വന്തം നഗരത്തിലേക്ക് തീർച്ചയായും തിരികെ കൊണ്ടുപോകും. പക്ഷേ, കുറ്റമറ്റവളേ, രാമൻ തിരിച്ചറിയുന്ന ഏതെങ്കിലും അടയാളം,",
        "0.29": "അദ്ദേഹത്തിന് സന്തോഷം നൽകുന്ന എന്തെങ്കിലും, ദയവായി തരൂ.' എല്ലാ ദിക്കുകളിലേക്കും നോക്കി, അവൾ തന്റെ മുടിയിൽനിന്ന് ശ്രേഷ്ഠമായ ആഭരണം എടുത്തു,",
        "0.30": "വസ്ത്രത്തിൽനിന്ന് അത് അഴിച്ച് ഈ രത്നം എനിക്ക് തന്നു, ശക്തനേ. രഘുവംശപ്രിയനേ, നിനക്കുവേണ്ടി ഞാൻ രണ്ടു കൈകൊണ്ടും ആ രത്നം സ്വീകരിച്ചു;",
        "0.31": "അവളെ തല കുനിച്ച് വണങ്ങി തിരിച്ചുപോകാൻ ഞാൻ ധൃതികൂട്ടി. ഞാൻ പോകാൻ ഉത്സുകനായതു കണ്ട് ആ സുന്ദരി,",
        "0.32": "ഞാൻ വലുതാകുന്നതു കണ്ട്, ജനകപുത്രി കണ്ണീരുകൊണ്ട് മുഖം മൂടി, ദയനീയയായി, കരച്ചിലാൽ ശബ്ദം ഇടറി എന്നോട് സംസാരിച്ചു;",
        "0.33": "ഞാൻ കുതിച്ചുയർന്നതിൽ പരിഭ്രമിച്ച്, ദുഃഖത്തിന്റെ പ്രവാഹത്താൽ പ്രഹരിക്കപ്പെട്ട്; പിന്നെ സീത എന്നോട് പറഞ്ഞു: 'നീ ഭാഗ്യവാനാണ്, മഹാവാനരാ,",
        "0.34": "ബലിഷ്ഠബാഹുവും താമരക്കണ്ണുമുള്ള രാമനെയും, എന്റെ ദേവരനായ ബലിഷ്ഠബാഹുവായ ലക്ഷ്മണനെയും നീ കാണും.'",
        "0.35": "സീത ഇങ്ങനെ പറഞ്ഞപ്പോൾ ഞാൻ മൈഥിലിയോട് പറഞ്ഞു: 'ദേവീ, ജനകപുത്രീ, വേഗം എന്റെ പുറത്ത് കയറൂ;",
        "0.36": "ഈ ദിവസംതന്നെ, സുഗ്രീവനോടും ലക്ഷ്മണനോടുമൊപ്പം നിന്റെ ഭർത്താവ് രാഘവനെ നിനക്ക് കാണിച്ചുതരാം, ശ്രേഷ്ഠയായ കറുത്ത കണ്ണുകളുള്ള സ്ത്രീയേ.'",
        "0.37": "അപ്പോൾ ദേവി എന്നോട് പറഞ്ഞു: 'മഹാവാനരാ, ഇത് ധർമ്മമല്ല; വാനരശ്രേഷ്ഠാ, എന്റെ ഇഷ്ടപ്രകാരം ഞാൻ നിന്റെ പുറത്ത് കയറുന്നത്.'",
        "0.38": "ഒരിക്കൽ ഞാൻ രാക്ഷസനാൽ ശരീരത്തിൽ സ്പർശിക്കപ്പെട്ടിട്ടുണ്ട്, വീരാ; അന്ന് വിധിയാൽ കീഴടക്കപ്പെട്ട് ഞാൻ എന്ത് ചെയ്യാൻ കഴിയുമായിരുന്നു?",
        "0.39": "വാനരശ്രേഷ്ഠാ, പോകൂ, ആ രണ്ടു രാജപുത്രന്മാർ ഇരിക്കുന്നിടത്തേക്ക്.' ഇത് പറഞ്ഞ്, അവൾ എനിക്ക് വീണ്ടും ഒരു സന്ദേശം കൂടി നൽകി:",
        "0.40": "'ഹനുമാനേ, സിംഹസമാനരായ ആ രണ്ടുപേരോടും, രാമനോടും ലക്ഷ്മണനോടും, മന്ത്രിമാരോടുകൂടിയ സുഗ്രീവനോടും, അവരെല്ലാവരോടും പറയൂ: ഞാൻ സുഖമായിരിക്കുന്നു എന്ന്.",
        "0.41": "ദുഃഖമാകുന്ന വെള്ളപ്പൊക്കത്തിൽ മുങ്ങിയ ഈ തടവറയിൽനിന്ന് ബലിഷ്ഠബാഹുവായ രാഘവൻ എന്നെ എങ്ങനെ രക്ഷിക്കുമെന്ന് നിങ്ങൾ അവരോട് പറയണം.",
        "0.42": "നീ രാമനെ എത്തുമ്പോൾ, എന്റെ ദുഃഖത്തിന്റെ ഈ ഭയങ്കര പ്രവാഹത്തെയും, ഈ രാക്ഷസരുടെ ഭീഷണികളെയും കുറിച്ച് പറയൂ. വാനരവീരാ, നിന്റെ യാത്ര സുരക്ഷിതമാകട്ടെ.'",
        "0.43": "രാജാവേ, ആത്മനിയന്ത്രണമുള്ള, ഉദാത്തയായ നിന്റെ സീത ദുഃഖത്തോടെ നിന്നോട് പറഞ്ഞ വാക്കുകൾ ഇവയാണ്. പറഞ്ഞത് അതുപോലെതന്നെ അറിഞ്ഞ്, സീത പൂർണ്ണമായും സുരക്ഷിതയും സുഖമായുമിരിക്കുന്നു എന്ന് വിശ്വസിക്കൂ.",
        "0.44": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപത്തേഴാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "ഹനുമാൻ സീതയുടെ വാക്കുകൾ രാമനോട് ആവർത്തിക്കുന്നു; അടയാളമായി കാകന്റെ കഥയും പറയുന്നു. സീത വേഗം വരണമെന്ന് രാമനോട് അപേക്ഷിച്ചതും, അവൾക്ക് ഇനി കുറച്ചുകാലം മാത്രമേ ജീവിക്കാനാകൂ എന്ന് അറിയിച്ചതും അവൻ പറയുന്നു."
    },
    "sundarakanda-68": {
      "verses": {
        "0.0": "\"പിന്നെ, മനുഷ്യരിൽ വ്യാഘ്രമായവനേ, നിന്നോടുള്ള സ്നേഹത്താലും സൗഹൃദത്താലും, ദേവി ആദ്യം എന്നെ ആദരിച്ച ശേഷം, ഉത്കണ്ഠയോടെ മറുപടിയായി വീണ്ടും എന്നോട് പറഞ്ഞു:",
        "0.1": "'ദശരഥപുത്രനായ രാമനോട് പല വിധത്തിലും നീ പറയണം; രാവണനെ യുദ്ധത്തിൽ വധിച്ച്, എന്നെ വേഗം തിരികെ നേടാൻ അദ്ദേഹത്തിന് കഴിയട്ടെ.",
        "0.2": "അല്ലെങ്കിൽ, വീരാ, ശത്രുക്കളെ അടക്കുന്നവനേ, ഉചിതമെന്ന് തോന്നുന്നെങ്കിൽ ഒരു ദിവസം ഏതെങ്കിലും മറഞ്ഞ സ്ഥലത്ത് താമസിക്കൂ; വിശ്രമിച്ചശേഷം നാളെ പോകാം.",
        "0.3": "വാനരാ, നിന്റെ സാന്നിധ്യത്താൽ, ഭാഗ്യദോഷിയായ ഞാനും, ഈ ദുഃഖത്തിന്റെ കയ്പുള്ള ഫലത്തിൽനിന്ന് ഒരു നിമിഷം ആശ്വാസം കണ്ടെത്തിയേക്കാം.",
        "0.4": "വീരാ, നീ പോയാൽ, നീ വീണ്ടും വരുന്നതുവരെ എന്റെ ജീവൻപോലും സംശയത്തിലാകും; ഇതിൽ ചോദ്യമില്ല.",
        "0.5": "നിന്നെ കാണാത്തതിന്റെ ദുഃഖം എന്നെ കൂടുതൽ പീഡിപ്പിക്കും; ദുഃഖത്തിനുമേൽ ദുഃഖം ഞെരിച്ച്, ദയനീയയായി, കഷ്ടപ്പെടാൻ ജനിച്ച എന്നെ.",
        "0.6": "വീരാ, വാനരപ്രഭോ, നിന്റെ സഖ്യകക്ഷികളായ വാനരന്മാരെയും കരടികളെയും കുറിച്ച് ഈ വലിയ സംശയം എന്റെ മുന്നിൽ നിൽക്കുന്നതുപോലെ തോന്നുന്നു:",
        "0.7": "മനുഷ്യശ്രേഷ്ഠരായ ആ രണ്ടു പുത്രന്മാരും, വാനരന്മാരുടെയും കരടികളുടെയും ആ സൈന്യങ്ങളും, കടക്കാനാവാത്ത ആ വലിയ സമുദ്രം എങ്ങനെ കടക്കും?",
        "0.8": "ഈ സമുദ്രം ചാടിക്കടക്കാൻ മൂന്നു പേർക്കുമാത്രമേ കഴിവുള്ളൂ: വിനതയുടെ പുത്രനായ ഗരുഡൻ, വായു, പിന്നെ നീ, കുറ്റമറ്റവനേ.",
        "0.9": "അതിനാൽ, വീരാ, ഇത്ര കഠിനമായ ഈ ദൗത്യത്തിൽ, നിനക്ക് എന്ത് പരിഹാരമാണ് കാണുന്നത്? പറയൂ, കർമ്മം അറിയുന്നവരിൽ ശ്രേഷ്ഠനേ.",
        "0.10": "നിശ്ചയം, ഈ ദൗത്യം നിറവേറ്റാൻ നീ മാത്രം മതി, ശത്രുവീരന്മാരെ വധിക്കുന്നവനേ; നിന്റെ ശക്തിയുടെ ഉയർച്ച മഹിമ കൊണ്ടുവരുന്നു.",
        "0.11": "പക്ഷേ രാമൻ, തന്റെ സൈന്യമെല്ലാം ഒന്നിച്ച്, രാവണനെ യുദ്ധത്തിൽ വധിച്ച്, വിജയിയായി എന്നെ സ്വന്തം നഗരത്തിലേക്ക് കൊണ്ടുപോയാൽ, അത് അദ്ദേഹത്തിന് മഹിമ നൽകും.",
        "0.12": "വനത്തിൽനിന്ന് ഒരു രാക്ഷസൻ വഞ്ചനയാൽ എന്നെ അപഹരിച്ചതുപോലെ, ആ വീരനെ ഭയന്ന്, രാഘവന് എന്നെ വീണ്ടെടുക്കുന്നത് യോജിക്കില്ല.",
        "0.13": "എന്നാൽ ശത്രുസൈന്യങ്ങളെ തകർക്കുന്ന കാകുത്സ്ഥൻ തന്റെ സൈന്യംകൊണ്ട് ലങ്കയെ നിറച്ച് എന്നെ തിരികെ കൊണ്ടുപോയാൽ, അത് അദ്ദേഹത്തിന് യോഗ്യമാകും.",
        "0.14": "അതിനാൽ, യുദ്ധത്തിൽ ആ മഹാത്മാവായ വീരന്റെ വീര്യത്തിന് യോജിക്കുന്നത് സംഭവിക്കുന്ന വിധത്തിൽ ചെയ്യണം.'",
        "0.15": "അവളുടെ അർത്ഥപൂർണ്ണവും വിനയമുള്ളതും യുക്തിയുക്തവുമായ വാക്കുകൾ കേട്ട്, ഞാൻ അവൾക്ക് എന്റെ അന്തിമ മറുപടി നൽകി:",
        "0.16": "\"ദേവീ, വാനരന്മാരുടെയും കരടികളുടെയും സൈന്യങ്ങളുടെ നാഥനായ, കുതിക്കുന്നവരിൽ ശ്രേഷ്ഠനായ, ശക്തിയോടെ നിറഞ്ഞ സുഗ്രീവൻ നിന്റെ കാര്യത്തിൽ ഉറച്ചിരിക്കുന്നു.",
        "0.17": "അദ്ദേഹത്തിന്റെ കല്പനയ്ക്കുകീഴിൽ വീര്യമുള്ള, ബലവാന്മാരും ശക്തരുമായ, ചിന്തപോലെ വേഗമുള്ള വാനരന്മാരുണ്ട്.",
        "0.18": "അവരുടെ ഗതി മുകളിലേക്കോ താഴേക്കോ വശങ്ങളിലേക്കോ തടയപ്പെടുന്നില്ല; അതിരില്ലാത്ത ഊർജ്ജമുള്ളവർ വലിയ ദൗത്യങ്ങളിൽ ഒരിക്കലും തളരുന്നില്ല.",
        "0.19": "വീണ്ടും വീണ്ടും, ആ ശ്രേഷ്ഠരായ, ശക്തരായ വാനരന്മാർ, വായുവിന്റെ പാത പിന്തുടർന്ന്, മുഴുവൻ ഭൂമിയും വലംവെച്ചിട്ടുണ്ട്.",
        "0.20": "അവിടെ എന്നെക്കാൾ മികച്ചവരും എന്നോട് തുല്യരുമായ വനവാസികളുണ്ട്; സുഗ്രീവന്റെ കൂട്ടത്തിൽ ആരും എന്നെക്കാൾ താഴ്ന്നവരല്ല.",
        "0.21": "എനിക്ക് ഇവിടേക്ക് വരാൻ കഴിയുമെങ്കിൽ, ആ ശക്തരായവർക്ക് എത്രയധികം കഴിയും! ശ്രേഷ്ഠരെ ദൂതന്മാരായി അയക്കാറില്ല; താഴ്ന്നവരെയാണ് അയക്കുന്നത്.",
        "0.22": "അതിനാൽ ദുഃഖം മതി, ദേവീ; നിന്റെ വിഷാദം അകലട്ടെ. ഒറ്റ കുതിപ്പിൽ വാനരനേതാക്കൾ ലങ്കയിലെത്തും.",
        "0.23": "ഉദിച്ച സൂര്യനെയും ചന്ദ്രനെയും പോലെ എന്റെ പുറത്ത് കയറി ആ രണ്ടു മനുഷ്യസിംഹങ്ങൾ, ഉദാത്തയായവളേ, നിന്റെ അടുത്തേക്ക് വരും.",
        "0.24": "ഉടൻ നീ ശത്രുക്കളെ വധിക്കുന്ന രാഘവനെ സിംഹംപോലെയും, വില്ല് കൈയിലുള്ള ലക്ഷ്മണനെയും ലങ്കയുടെ ഗോപുരവാതിൽക്കൽ എത്തിയതായി കാണും.",
        "0.25": "ഉടൻ നീ നഖങ്ങളും കോമ്പല്ലുകളുമുള്ള വീരന്മാരായ വാനരന്മാർ, സിംഹങ്ങളുടെയും കടുവകളുടെയും വീര്യത്തോടെ, ഗംഭീര ആനകളെപ്പോലെ ഒന്നിച്ചുകൂടിയതായി കാണും.",
        "0.26": "താമസിയാതെ, ലങ്കയിലെ മലയപർവ്വതത്തിന്റെ ചരിവുകളിൽ, പർവ്വതങ്ങളും മേഘങ്ങളും പോലെ ഇടിമുഴക്കുന്ന പ്രധാന വാനരന്മാരുടെ ഗർജ്ജനം നീ കേൾക്കും.",
        "0.27": "ഉടൻ തന്നെ ശത്രുക്കളെ അടക്കുന്ന രാഘവൻ, വനവാസത്തിന്റെ കാലം അവസാനിച്ച്, നിന്നോടൊപ്പം അയോധ്യയിൽ രാജാവായി അഭിഷിക്തനായതായി നീ കാണും.'",
        "0.28": "അങ്ങനെ ശുഭകരവും ഹൃദ്യവുമായ വാക്കുകളാൽ ഞാൻ ആശ്വസിപ്പിച്ചപ്പോൾ, നിന്നെക്കുറിച്ചുള്ള ദുഃഖത്താൽ അതിയായി പീഡിതയായിരുന്നിട്ടും, മിഥിലാരാജപുത്രി, പതറാതെ സംസാരിക്കുന്നവൾ, സമാധാനം കണ്ടെത്തി.\"",
        "0.29": "വാല്മീകിയുടെ ആദികാവ്യമായ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അറുപത്തെട്ടാം സർഗ്ഗം ഇവിടെ സമാപിച്ചു."
      },
      "summary": "സമുദ്രം കടക്കുന്നതിനെക്കുറിച്ചുള്ള സീതയുടെ സംശയങ്ങളും, രാമനും വാനരസൈന്യവും വേഗം വരുമെന്ന് താൻ അവളെ ആശ്വസിപ്പിച്ചതും ഹനുമാൻ രാമനോട് വിവരിക്കുന്നു. പ്രത്യാശയുടെ ഈ സന്ദേശത്തോടെ സുന്ദരകാണ്ഡം അവസാനിക്കുന്നു."
    }
  },
};
